insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (72, 4, 56, 70, 'سورة النساء ٥٦ – ٧٠', 'أداء الأمانات وطاعة أولي الأمر، و«فلا وربك لا يؤمنون حتى يحكّموك»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 72) = $j$[{"lbl": "الآيتان ٥٦ – ٥٧", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارٗا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمٗا ﴿٥٦﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَنُدۡخِلُهُمۡ ظِلّٗا ظَلِيلًا ﴿٥٧﴾", "w": [["نصليهم ناراً", "ندخلهم ناراً يحترقون بها."], ["نضجت جلودهم", "تهرّأت وتساقطت."], ["ليذوقوا العذاب", "ليستمر لهم العذاب مؤلماً."], ["عزيزاً حكيماً", "غالباً، يعذّب من يستحق العذاب."], ["تجري من تحتها الأنهار", "تجري من خلال أشجارها وقصورها الأنهار."], ["مطهّرة", "من الأذى والقذى مطلقاً."], ["ظلاً ظليلاً", "الوارف الدائم لا حرّ فيه ولا برد."]], "m": "على ذكر الإيمان والكفر في الآية السابقة، ذكر الله الوعيد لأهل الكفر والوعد لأهل الإيمان: إن الذين كفروا بآياتنا سوف ندخلهم نار جهنم يحترقون فيها، كلما نضجت جلودهم فتهرّأت وسقطت بدّلهم الله فوراً جلوداً غيرها، ليتجدّد ذوقهم للعذاب وإحساسهم به، إن الله كان عزيزاً لا يعجز عن إنفاذ وعيده، حكيماً في تدبيره. والذين آمنوا وعملوا الصالحات، بعد تركهم الشرك والمعاصي، سندخلهم جنات تجري من تحتها الأنهار خالدين فيها أبداً، لهم فيها أزواج من الحور العين مطهّرات من كل ما يؤذي أو يخلّ بحسنهن، وندخلهم ظلاً ظليلاً وارفاً يقيهم الحر والبرد، وقد حدّث رسول الله ﷺ أن في الجنة شجرة يسير الراكب في ظلها مائة سنة ما يقطعه.", "h": ["الكفر والمعاصي موجبات للعذاب الأخروي.", "بيان الحكمة في تبديل الجلود لأهل النار، وهي أن يدوم إحساسهم بالعذاب.", "الإيمان والعمل الصالح مع ترك الشرك والمعاصي موجبات للنعيم الأخروي.", "الجنة دار النعيم، خالية من مكدّرات الصفو والسعادة."], "k": "ظلٌّ لا حرّ فيه ولا برد، ونعيم لا يكدّره شيء… ما العمل الذي أقدّمه اليوم لذلك الظل؟"}, {"lbl": "الآيتان ٥٨ – ٥٩", "q": "۞إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا ﴿٥٨﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا ﴿٥٩﴾", "w": [["أن تؤدّوا الأمانات", "أداء الأمانة: تسليمها إلى صاحبها، والأمانة ما يؤتمن عليه المرء من قول أو عمل أو متاع."], ["العدل", "ضد الجور والانحراف بنقص أو زيادة."], ["نِعمّا يعظكم به", "نعم شيء يأمركم به: أداء الأمانات والحكم بالعدل."], ["وأولي الأمر منكم", "الأمراء والعلماء من المسلمين."], ["تنازعتم في شيء", "اختلفتم فيه، كل فريق يريد أن ينتزعه من يد الآخر."], ["فردّوه إلى الله والرسول", "إلى كتاب الله وسنة رسوله ﷺ."], ["وأحسن تأويلاً", "أحسن عاقبة، لأن تأويل الشيء ما يؤول إليه."]], "m": "رُوي أن الآية نزلت في عثمان بن طلحة الحجبي، كان مفتاح الكعبة عنده بوصفه سادناً، فأخذه منه رسول الله ﷺ صبيحة يوم الفتح فصلّى في البيت ركعتين، فقال العباس: أعطنيه يا رسول الله ليجمع بين السقاية والسدانة، فنزلت، فقرأها ﷺ على الناس وأعطى عثمان المفتاح. والعبرة بعموم اللفظ، فعلى كل مؤتمن على شيء أن يحفظه حتى يؤدّيه إلى صاحبه، وتتناول الآية حكّام المسلمين أولاً: «وإذا حكمتم بين الناس أن تحكموا بالعدل»، بإيصال الحقوق إلى مستحقيها، ونِعمّا يعظكم به، إذ قوام الحياة الكريمة أداء الأمانات والحكم بالعدل، إن الله كان سميعاً بصيراً، فمن ذكر أن الله يسمع أقواله ويبصر أعماله استقام. ثم لما أمر الولاة بأداء حقوق الرعية، أمر الرعية بطاعة الله ورسوله أولاً، ثم بطاعة ولاة الأمر في المعروف، إذ «لا طاعة لمخلوق في معصية الخالق». فإن تنازعتم، ولاةً ورعية، في أمر من أمور الدين أو الدنيا فردّوه إلى الكتاب والسنة، فما حكما به وجب قبوله حلواً كان أو مرّاً، إن كنتم تؤمنون بالله واليوم الآخر، فالإيمان يستلزم الإذعان لحكم الله ورسوله، ذلك خير وأحسن عاقبة، لما فيه من قطع النزاع والسير بالأمة متحدة متحابة.", "h": ["وجوب ردّ الأمانات بعد المحافظة عليها.", "وجوب العدل في الحكم، وحرمة الحيف والجور فيه.", "وجوب طاعة الله ورسوله وولاة المسلمين من حكام وعلماء فقهاء؛ لأن طاعة الرسول من طاعة الله، وطاعة الوالي من طاعة الرسول ﷺ.", "وجوب ردّ المتنازع فيه، عقيدةً أو عبادةً أو قضاءً، إلى الكتاب والسنة، ووجوب الرضا بحكمهما.", "العاقبة الحميدة والحال السعيدة في ردّ الأمة ما تتنازع فيه إلى كتاب ربها وسنة نبيها ﷺ."], "k": "ما الأمانات التي في يدي الآن: مالٌ، أو سرٌّ، أو عمل، أو أولاد؟ وهل أؤدّيها كما يحب الله؟"}, {"lbl": "الآيات ٦٠ – ٦٣", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يَزۡعُمُونَ أَنَّهُمۡ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّـٰغُوتِ وَقَدۡ أُمِرُوٓاْ أَن يَكۡفُرُواْ بِهِۦۖ وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ ضَلَٰلَۢا بَعِيدٗا ﴿٦٠﴾ وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيۡتَ ٱلۡمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودٗا ﴿٦١﴾ فَكَيۡفَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ ثُمَّ جَآءُوكَ يَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَآ إِلَّآ إِحۡسَٰنٗا وَتَوۡفِيقًا ﴿٦٢﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا فِي قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِيٓ أَنفُسِهِمۡ قَوۡلَۢا بَلِيغٗا ﴿٦٣﴾", "w": [["يزعمون", "يقولون كاذبين."], ["بما أُنزل إليك", "القرآن، وما أُنزل من قبلك: التوراة."], ["الطاغوت", "كل ما عُبد من دون الله ورضي بالعبادة، والمراد به هنا كعب بن الأشرف اليهودي أو كاهن من كهان العرب."], ["المنافقين", "جمع منافق، وهو من يبطن الكفر ويظهر الإيمان."], ["يصدّون", "يُعرضون عنك ويصرفون غيرهم كذلك."], ["مصيبة", "عقوبة بسبب كفرهم ونفاقهم."], ["إن أردنا", "ما أردنا."], ["إلا إحساناً", "صلحاً بين المتخاصمين."], ["وتوفيقاً", "جمعاً وتأليفاً بين المختلفين."], ["فأعرض عنهم", "اصفح عنهم فلا تؤاخذهم."], ["وعِظهم", "مُرهم بما ينبغي لهم ويجب عليهم."], ["قولاً بليغاً", "كلاماً قوياً يبلغ شغاف قلوبهم."]], "m": "رُوي أن منافقاً ويهودياً اختلفا في شيء، فقال اليهودي: نتحاكم إلى محمد ﷺ، لعلمه أنه يحكم بالعدل ولا يأخذ رشوة، وقال المنافق: نتحاكم إلى كعب بن الأشرف، فتحاكما إلى رسول الله ﷺ فقضى لليهودي، فنزلت: ألم ينتهِ إلى علمك أمر الذين يزعمون أنهم آمنوا بما أُنزل إليك وما أُنزل من قبلك، يريدون أن يتحاكموا إلى الطاغوت وقد أُمروا أن يكفروا به، ويريد الشيطان أن يضلّهم ضلالاً بعيداً. وإذا قيل لهم: تعالوا إلى ما أنزل الله وإلى الرسول، رأيت المنافقين يُعرضون عنك هاربين من حكمك. فكيف إذا أصابتهم مصيبة بسبب ذنوبهم، ثم جاؤوك يحلفون بالله: ما أردنا إلا الإحسان والتوفيق بين المتخاصمين؟ أولئك الذين يعلم الله ما في قلوبهم من النفاق والزيغ، فأعرض عنهم فلا تؤاخذهم، وعِظهم بتقوى الله والإسلام له ظاهراً وباطناً، وقل لهم في خاصة أنفسهم قولاً بليغاً ينفذ إلى قلوبهم فيذهب غفلتها، لعلهم يرجعون.", "h": ["حرمة التحاكم إلى غير كتاب الله وسنة رسوله ﷺ إذا وُجد عالم بهما.", "وجوب الكفر بالطاغوت أيّاً كان نوعه.", "وجوب الدعوة إلى التحاكم إلى الكتاب والسنة، ووجوب قبولها.", "استحباب الإعراض عن ذوي الجهالات، ووعظهم بالقول البليغ الذي يصل إلى قلوبهم فيهزّها."], "k": "حين يخالف حكمُ الله هواي… هل أبحث عن «فتوى» تُرضيني، أم أُسلّم؟"}, {"lbl": "الآيتان ٦٤ – ٦٥", "q": "وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوٓاْ أَنفُسَهُمۡ جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُواْ ٱللَّهَ تَوَّابٗا رَّحِيمٗا ﴿٦٤﴾ فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا ﴿٦٥﴾", "w": [["بإذن الله", "إعلامه بالشيء وأمره به."], ["ظلموا أنفسهم", "بالتحاكم إلى الطاغوت وتركهم التحاكم إلى رسول الله ﷺ."], ["استغفروا الله", "طلبوا منه أن يغفر لهم."], ["يحكّموك", "يجعلونك حكماً بينهم ويفوّضون الأمر إليك."], ["فيما شجر بينهم", "فيما اختلفوا فيه لاختلاط وجه الحق والصواب فيه بالخطأ والباطل."], ["حرجاً", "ضيقاً وتحرّجاً."], ["مما قضيت", "مما حكمت فيه."], ["ويسلّموا تسليماً", "يذعنوا لقبول حكمك تسليماً تاماً."]], "m": "بعد تقرير ضلال من أرادا التحاكم إلى الطاغوت، أخبر الله أنه ما أرسل رسولاً إلا وأمر المرسَل إليهم بطاعته واتباعه والتحاكم إليه بإذنه. وأخبر أن أولئك الظالمين لأنفسهم لو جاؤوك متنصّلين من خطيئتهم، مستغفرين الله، واستغفرت لهم، لدلّ ذلك على توبتهم، ولوجدوا الله تواباً رحيماً. ثم أقسم تعالى بنفسه: «فلا وربك لا يؤمنون حتى يحكّموك فيما شجر بينهم»، أي يطلبون حكمك فيما اختلفوا فيه واختلط عليهم من أمورهم، ثم بعد حكمك لا يجدون في صدورهم أدنى شك في صحة حكمك وعدالته، أو في التسليم له والرضا به، وهو معنى الحرج المنفيّ في قوله: «ثم لا يجدوا في أنفسهم حرجاً مما قضيت ويسلّموا تسليماً».", "h": ["وجوب طاعة الرسول ﷺ فيما يأمر به وينهى عنه.", "بطلان من يزعم أن في الآية دليلاً على جواز طلب الاستغفار من الرسول ﷺ بعد موته؛ لأنها نزلت في الرجلين اللذين أرادا التحاكم إلى كعب بن الأشرف، فاشترط لتوبتهما إتيانهما الرسول ﷺ واستغفاره لهما، أما من عداهما فتوبته لا تتوقف على ذلك، وهذا محل إجماع بين المسلمين.", "كل ذنب كبر أو صغر يُعتبر ظلماً للنفس، وتجب التوبة منه بالاستغفار والندم والعزم على عدم العودة إليه.", "وجوب التحاكم إلى الكتاب والسنة، وحرمة التحاكم إلى غيرهما.", "وجوب الرضا بحكم الله ورسوله والتسليم به."], "k": "«ثم لا يجدوا في أنفسهم حرجاً مما قضيت»… هل في صدري ضيق من حكمٍ شرعيّ؟ وكيف أعالجه؟"}, {"lbl": "الآيات ٦٦ – ٧٠", "q": "وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُواْ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيۡرٗا لَّهُمۡ وَأَشَدَّ تَثۡبِيتٗا ﴿٦٦﴾ وَإِذٗا لَّأٓتَيۡنَٰهُم مِّن لَّدُنَّآ أَجۡرًا عَظِيمٗا ﴿٦٧﴾ وَلَهَدَيۡنَٰهُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا ﴿٦٨﴾ وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَـٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّـٰلِحِينَۚ وَحَسُنَ أُوْلَـٰٓئِكَ رَفِيقٗا ﴿٦٩﴾ ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِيمٗا ﴿٧٠﴾", "w": [["كتبنا عليهم", "فرضنا عليهم وأوجبنا."], ["أن اقتلوا أنفسكم", "أي بقتل بعضكم بعضاً."], ["ما فعلوه إلا قليل منهم", "ما فعل القتل إلا قليل منهم."], ["ما يوعظون به", "ما يُؤمرون به ويُنهون عنه."], ["وأشدّ تثبيتاً", "للإيمان في قلوبهم."], ["الصدّيقين", "جمع صدّيق، وهو من غلب عليه الصدق في أقواله وأحواله لكثرة ما يصدق ويتحرّى الصدق."], ["والشهداء", "جمع شهيد: من مات في المعركة، ومثله من شهد بصحة الإسلام بالحجة والبرهان."], ["والصالحين", "جمع صالح: من أدّى حقوق الله وحقوق العباد، وصلحت نفسه وعمله، وغلب صلاحه على فساده."]], "m": "ما زال السياق في أولئك النفر الذين أرادوا التحاكم إلى الطاغوت، فقال تعالى: لو أنا فرضنا عليهم أن يقتلوا أنفسهم، كما حصل لبني إسرائيل، أو أن يخرجوا من ديارهم مهاجرين، ما فعله إلا قليل منهم. ثم رغّبهم في الهداية: ولو أنهم فعلوا ما يوعظون به من الطاعة والتسليم لكان خيراً لهم في الحال والمآل، وأشدّ تثبيتاً للإيمان في قلوبهم وللطاعة على جوارحهم؛ لأن الإيمان يزيد بالطاعة وينقص بالمعصية، والحسنة تنتج حسنة والسيئة تتولّد عنها سيئة، ولأعطيناهم من لدنّا أجراً عظيماً، ولهديناهم صراطاً مستقيماً، وهو الإسلام، بتوفيقهم للسير فيه. ثم قال: «ومن يطع الله والرسول فأولئك مع الذين أنعم الله عليهم من النبيين والصدّيقين والشهداء والصالحين»، نزلت حين قال بعض الصحابة: يا رسول الله، ما ينبغي لنا أن نفارقك في الدنيا، فإنك إذا فارقتنا رُفعت فوقنا فلم نرك. ونعمة الله عليهم في الدنيا الإيمان ومعرفة محابّه ومساخطه والتوفيق لفعلها وتركها، وفي الآخرة الجوار الكريم في دار النعيم، وحسُن أولئك رفيقاً في الجنة، ينزلون إليهم ثم يعودون إلى منازلهم العالية. ذلك الفضل من الله، لا بطاعتهم، وكفى بالله عليماً.", "h": ["قد يكلّف الله تعالى بالشاق للامتحان والابتلاء، كقتل النفس والهجرة من البلد، ولكن لا يكلّف بما لا يُطاق.", "الإيمان يزيد بالطاعات، وينقص بالمعاصي.", "الطاعات تثمر قوة الإيمان، وتؤهّل لدخول الجنان.", "مرافقة النبيين والصدّيقين والشهداء والصالحين في الجنة ثمرة من ثمار طاعة الله والرسول ﷺ."], "k": "«وحسُن أولئك رفيقاً»… من رفقائي في الدنيا؟ وهل يقرّبونني من هذه الرفقة في الجنة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 72;
insert into public.tdb_cards(topic, i, body) select 72, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٥٦ – ٥٧", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارٗا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمٗا ﴿٥٦﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَنُدۡخِلُهُمۡ ظِلّٗا ظَلِيلًا ﴿٥٧﴾", "w": [["نصليهم ناراً", "ندخلهم ناراً يحترقون بها."], ["نضجت جلودهم", "تهرّأت وتساقطت."], ["ليذوقوا العذاب", "ليستمر لهم العذاب مؤلماً."], ["عزيزاً حكيماً", "غالباً، يعذّب من يستحق العذاب."], ["تجري من تحتها الأنهار", "تجري من خلال أشجارها وقصورها الأنهار."], ["مطهّرة", "من الأذى والقذى مطلقاً."], ["ظلاً ظليلاً", "الوارف الدائم لا حرّ فيه ولا برد."]], "m": "على ذكر الإيمان والكفر في الآية السابقة، ذكر الله الوعيد لأهل الكفر والوعد لأهل الإيمان: إن الذين كفروا بآياتنا سوف ندخلهم نار جهنم يحترقون فيها، كلما نضجت جلودهم فتهرّأت وسقطت بدّلهم الله فوراً جلوداً غيرها، ليتجدّد ذوقهم للعذاب وإحساسهم به، إن الله كان عزيزاً لا يعجز عن إنفاذ وعيده، حكيماً في تدبيره. والذين آمنوا وعملوا الصالحات، بعد تركهم الشرك والمعاصي، سندخلهم جنات تجري من تحتها الأنهار خالدين فيها أبداً، لهم فيها أزواج من الحور العين مطهّرات من كل ما يؤذي أو يخلّ بحسنهن، وندخلهم ظلاً ظليلاً وارفاً يقيهم الحر والبرد، وقد حدّث رسول الله ﷺ أن في الجنة شجرة يسير الراكب في ظلها مائة سنة ما يقطعه.", "h": ["الكفر والمعاصي موجبات للعذاب الأخروي.", "بيان الحكمة في تبديل الجلود لأهل النار، وهي أن يدوم إحساسهم بالعذاب.", "الإيمان والعمل الصالح مع ترك الشرك والمعاصي موجبات للنعيم الأخروي.", "الجنة دار النعيم، خالية من مكدّرات الصفو والسعادة."], "k": "ظلٌّ لا حرّ فيه ولا برد، ونعيم لا يكدّره شيء… ما العمل الذي أقدّمه اليوم لذلك الظل؟"}, {"lbl": "الآيتان ٥٨ – ٥٩", "q": "۞إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا ﴿٥٨﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا ﴿٥٩﴾", "w": [["أن تؤدّوا الأمانات", "أداء الأمانة: تسليمها إلى صاحبها، والأمانة ما يؤتمن عليه المرء من قول أو عمل أو متاع."], ["العدل", "ضد الجور والانحراف بنقص أو زيادة."], ["نِعمّا يعظكم به", "نعم شيء يأمركم به: أداء الأمانات والحكم بالعدل."], ["وأولي الأمر منكم", "الأمراء والعلماء من المسلمين."], ["تنازعتم في شيء", "اختلفتم فيه، كل فريق يريد أن ينتزعه من يد الآخر."], ["فردّوه إلى الله والرسول", "إلى كتاب الله وسنة رسوله ﷺ."], ["وأحسن تأويلاً", "أحسن عاقبة، لأن تأويل الشيء ما يؤول إليه."]], "m": "رُوي أن الآية نزلت في عثمان بن طلحة الحجبي، كان مفتاح الكعبة عنده بوصفه سادناً، فأخذه منه رسول الله ﷺ صبيحة يوم الفتح فصلّى في البيت ركعتين، فقال العباس: أعطنيه يا رسول الله ليجمع بين السقاية والسدانة، فنزلت، فقرأها ﷺ على الناس وأعطى عثمان المفتاح. والعبرة بعموم اللفظ، فعلى كل مؤتمن على شيء أن يحفظه حتى يؤدّيه إلى صاحبه، وتتناول الآية حكّام المسلمين أولاً: «وإذا حكمتم بين الناس أن تحكموا بالعدل»، بإيصال الحقوق إلى مستحقيها، ونِعمّا يعظكم به، إذ قوام الحياة الكريمة أداء الأمانات والحكم بالعدل، إن الله كان سميعاً بصيراً، فمن ذكر أن الله يسمع أقواله ويبصر أعماله استقام. ثم لما أمر الولاة بأداء حقوق الرعية، أمر الرعية بطاعة الله ورسوله أولاً، ثم بطاعة ولاة الأمر في المعروف، إذ «لا طاعة لمخلوق في معصية الخالق». فإن تنازعتم، ولاةً ورعية، في أمر من أمور الدين أو الدنيا فردّوه إلى الكتاب والسنة، فما حكما به وجب قبوله حلواً كان أو مرّاً، إن كنتم تؤمنون بالله واليوم الآخر، فالإيمان يستلزم الإذعان لحكم الله ورسوله، ذلك خير وأحسن عاقبة، لما فيه من قطع النزاع والسير بالأمة متحدة متحابة.", "h": ["وجوب ردّ الأمانات بعد المحافظة عليها.", "وجوب العدل في الحكم، وحرمة الحيف والجور فيه.", "وجوب طاعة الله ورسوله وولاة المسلمين من حكام وعلماء فقهاء؛ لأن طاعة الرسول من طاعة الله، وطاعة الوالي من طاعة الرسول ﷺ.", "وجوب ردّ المتنازع فيه، عقيدةً أو عبادةً أو قضاءً، إلى الكتاب والسنة، ووجوب الرضا بحكمهما.", "العاقبة الحميدة والحال السعيدة في ردّ الأمة ما تتنازع فيه إلى كتاب ربها وسنة نبيها ﷺ."], "k": "ما الأمانات التي في يدي الآن: مالٌ، أو سرٌّ، أو عمل، أو أولاد؟ وهل أؤدّيها كما يحب الله؟"}, {"lbl": "الآيات ٦٠ – ٦٣", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يَزۡعُمُونَ أَنَّهُمۡ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّـٰغُوتِ وَقَدۡ أُمِرُوٓاْ أَن يَكۡفُرُواْ بِهِۦۖ وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ ضَلَٰلَۢا بَعِيدٗا ﴿٦٠﴾ وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيۡتَ ٱلۡمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودٗا ﴿٦١﴾ فَكَيۡفَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ ثُمَّ جَآءُوكَ يَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَآ إِلَّآ إِحۡسَٰنٗا وَتَوۡفِيقًا ﴿٦٢﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا فِي قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِيٓ أَنفُسِهِمۡ قَوۡلَۢا بَلِيغٗا ﴿٦٣﴾", "w": [["يزعمون", "يقولون كاذبين."], ["بما أُنزل إليك", "القرآن، وما أُنزل من قبلك: التوراة."], ["الطاغوت", "كل ما عُبد من دون الله ورضي بالعبادة، والمراد به هنا كعب بن الأشرف اليهودي أو كاهن من كهان العرب."], ["المنافقين", "جمع منافق، وهو من يبطن الكفر ويظهر الإيمان."], ["يصدّون", "يُعرضون عنك ويصرفون غيرهم كذلك."], ["مصيبة", "عقوبة بسبب كفرهم ونفاقهم."], ["إن أردنا", "ما أردنا."], ["إلا إحساناً", "صلحاً بين المتخاصمين."], ["وتوفيقاً", "جمعاً وتأليفاً بين المختلفين."], ["فأعرض عنهم", "اصفح عنهم فلا تؤاخذهم."], ["وعِظهم", "مُرهم بما ينبغي لهم ويجب عليهم."], ["قولاً بليغاً", "كلاماً قوياً يبلغ شغاف قلوبهم."]], "m": "رُوي أن منافقاً ويهودياً اختلفا في شيء، فقال اليهودي: نتحاكم إلى محمد ﷺ، لعلمه أنه يحكم بالعدل ولا يأخذ رشوة، وقال المنافق: نتحاكم إلى كعب بن الأشرف، فتحاكما إلى رسول الله ﷺ فقضى لليهودي، فنزلت: ألم ينتهِ إلى علمك أمر الذين يزعمون أنهم آمنوا بما أُنزل إليك وما أُنزل من قبلك، يريدون أن يتحاكموا إلى الطاغوت وقد أُمروا أن يكفروا به، ويريد الشيطان أن يضلّهم ضلالاً بعيداً. وإذا قيل لهم: تعالوا إلى ما أنزل الله وإلى الرسول، رأيت المنافقين يُعرضون عنك هاربين من حكمك. فكيف إذا أصابتهم مصيبة بسبب ذنوبهم، ثم جاؤوك يحلفون بالله: ما أردنا إلا الإحسان والتوفيق بين المتخاصمين؟ أولئك الذين يعلم الله ما في قلوبهم من النفاق والزيغ، فأعرض عنهم فلا تؤاخذهم، وعِظهم بتقوى الله والإسلام له ظاهراً وباطناً، وقل لهم في خاصة أنفسهم قولاً بليغاً ينفذ إلى قلوبهم فيذهب غفلتها، لعلهم يرجعون.", "h": ["حرمة التحاكم إلى غير كتاب الله وسنة رسوله ﷺ إذا وُجد عالم بهما.", "وجوب الكفر بالطاغوت أيّاً كان نوعه.", "وجوب الدعوة إلى التحاكم إلى الكتاب والسنة، ووجوب قبولها.", "استحباب الإعراض عن ذوي الجهالات، ووعظهم بالقول البليغ الذي يصل إلى قلوبهم فيهزّها."], "k": "حين يخالف حكمُ الله هواي… هل أبحث عن «فتوى» تُرضيني، أم أُسلّم؟"}, {"lbl": "الآيتان ٦٤ – ٦٥", "q": "وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوٓاْ أَنفُسَهُمۡ جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُواْ ٱللَّهَ تَوَّابٗا رَّحِيمٗا ﴿٦٤﴾ فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا ﴿٦٥﴾", "w": [["بإذن الله", "إعلامه بالشيء وأمره به."], ["ظلموا أنفسهم", "بالتحاكم إلى الطاغوت وتركهم التحاكم إلى رسول الله ﷺ."], ["استغفروا الله", "طلبوا منه أن يغفر لهم."], ["يحكّموك", "يجعلونك حكماً بينهم ويفوّضون الأمر إليك."], ["فيما شجر بينهم", "فيما اختلفوا فيه لاختلاط وجه الحق والصواب فيه بالخطأ والباطل."], ["حرجاً", "ضيقاً وتحرّجاً."], ["مما قضيت", "مما حكمت فيه."], ["ويسلّموا تسليماً", "يذعنوا لقبول حكمك تسليماً تاماً."]], "m": "بعد تقرير ضلال من أرادا التحاكم إلى الطاغوت، أخبر الله أنه ما أرسل رسولاً إلا وأمر المرسَل إليهم بطاعته واتباعه والتحاكم إليه بإذنه. وأخبر أن أولئك الظالمين لأنفسهم لو جاؤوك متنصّلين من خطيئتهم، مستغفرين الله، واستغفرت لهم، لدلّ ذلك على توبتهم، ولوجدوا الله تواباً رحيماً. ثم أقسم تعالى بنفسه: «فلا وربك لا يؤمنون حتى يحكّموك فيما شجر بينهم»، أي يطلبون حكمك فيما اختلفوا فيه واختلط عليهم من أمورهم، ثم بعد حكمك لا يجدون في صدورهم أدنى شك في صحة حكمك وعدالته، أو في التسليم له والرضا به، وهو معنى الحرج المنفيّ في قوله: «ثم لا يجدوا في أنفسهم حرجاً مما قضيت ويسلّموا تسليماً».", "h": ["وجوب طاعة الرسول ﷺ فيما يأمر به وينهى عنه.", "بطلان من يزعم أن في الآية دليلاً على جواز طلب الاستغفار من الرسول ﷺ بعد موته؛ لأنها نزلت في الرجلين اللذين أرادا التحاكم إلى كعب بن الأشرف، فاشترط لتوبتهما إتيانهما الرسول ﷺ واستغفاره لهما، أما من عداهما فتوبته لا تتوقف على ذلك، وهذا محل إجماع بين المسلمين.", "كل ذنب كبر أو صغر يُعتبر ظلماً للنفس، وتجب التوبة منه بالاستغفار والندم والعزم على عدم العودة إليه.", "وجوب التحاكم إلى الكتاب والسنة، وحرمة التحاكم إلى غيرهما.", "وجوب الرضا بحكم الله ورسوله والتسليم به."], "k": "«ثم لا يجدوا في أنفسهم حرجاً مما قضيت»… هل في صدري ضيق من حكمٍ شرعيّ؟ وكيف أعالجه؟"}, {"lbl": "الآيات ٦٦ – ٧٠", "q": "وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُواْ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيۡرٗا لَّهُمۡ وَأَشَدَّ تَثۡبِيتٗا ﴿٦٦﴾ وَإِذٗا لَّأٓتَيۡنَٰهُم مِّن لَّدُنَّآ أَجۡرًا عَظِيمٗا ﴿٦٧﴾ وَلَهَدَيۡنَٰهُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا ﴿٦٨﴾ وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَـٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّـٰلِحِينَۚ وَحَسُنَ أُوْلَـٰٓئِكَ رَفِيقٗا ﴿٦٩﴾ ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِيمٗا ﴿٧٠﴾", "w": [["كتبنا عليهم", "فرضنا عليهم وأوجبنا."], ["أن اقتلوا أنفسكم", "أي بقتل بعضكم بعضاً."], ["ما فعلوه إلا قليل منهم", "ما فعل القتل إلا قليل منهم."], ["ما يوعظون به", "ما يُؤمرون به ويُنهون عنه."], ["وأشدّ تثبيتاً", "للإيمان في قلوبهم."], ["الصدّيقين", "جمع صدّيق، وهو من غلب عليه الصدق في أقواله وأحواله لكثرة ما يصدق ويتحرّى الصدق."], ["والشهداء", "جمع شهيد: من مات في المعركة، ومثله من شهد بصحة الإسلام بالحجة والبرهان."], ["والصالحين", "جمع صالح: من أدّى حقوق الله وحقوق العباد، وصلحت نفسه وعمله، وغلب صلاحه على فساده."]], "m": "ما زال السياق في أولئك النفر الذين أرادوا التحاكم إلى الطاغوت، فقال تعالى: لو أنا فرضنا عليهم أن يقتلوا أنفسهم، كما حصل لبني إسرائيل، أو أن يخرجوا من ديارهم مهاجرين، ما فعله إلا قليل منهم. ثم رغّبهم في الهداية: ولو أنهم فعلوا ما يوعظون به من الطاعة والتسليم لكان خيراً لهم في الحال والمآل، وأشدّ تثبيتاً للإيمان في قلوبهم وللطاعة على جوارحهم؛ لأن الإيمان يزيد بالطاعة وينقص بالمعصية، والحسنة تنتج حسنة والسيئة تتولّد عنها سيئة، ولأعطيناهم من لدنّا أجراً عظيماً، ولهديناهم صراطاً مستقيماً، وهو الإسلام، بتوفيقهم للسير فيه. ثم قال: «ومن يطع الله والرسول فأولئك مع الذين أنعم الله عليهم من النبيين والصدّيقين والشهداء والصالحين»، نزلت حين قال بعض الصحابة: يا رسول الله، ما ينبغي لنا أن نفارقك في الدنيا، فإنك إذا فارقتنا رُفعت فوقنا فلم نرك. ونعمة الله عليهم في الدنيا الإيمان ومعرفة محابّه ومساخطه والتوفيق لفعلها وتركها، وفي الآخرة الجوار الكريم في دار النعيم، وحسُن أولئك رفيقاً في الجنة، ينزلون إليهم ثم يعودون إلى منازلهم العالية. ذلك الفضل من الله، لا بطاعتهم، وكفى بالله عليماً.", "h": ["قد يكلّف الله تعالى بالشاق للامتحان والابتلاء، كقتل النفس والهجرة من البلد، ولكن لا يكلّف بما لا يُطاق.", "الإيمان يزيد بالطاعات، وينقص بالمعاصي.", "الطاعات تثمر قوة الإيمان، وتؤهّل لدخول الجنان.", "مرافقة النبيين والصدّيقين والشهداء والصالحين في الجنة ثمرة من ثمار طاعة الله والرسول ﷺ."], "k": "«وحسُن أولئك رفيقاً»… من رفقائي في الدنيا؟ وهل يقرّبونني من هذه الرفقة في الجنة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (73, 4, 71, 79, 'سورة النساء ٧١ – ٧٩', 'خذوا حذركم، والقتال لإنقاذ المستضعفين، و«قل كلٌّ من عند الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 73) = $j$[{"lbl": "الآيات ٧١ – ٧٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعٗا ﴿٧١﴾ وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ فَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةٞ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِيدٗا ﴿٧٢﴾ وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِيمٗا ﴿٧٣﴾", "w": [["خذوا حذركم", "الحذر: الاحتراس والاستعداد لدفع المكروه بحسبه."], ["فانفروا ثُبات", "النفور: الخروج في اندفاع، والثُّبات: جمع ثُبة، وهي الجماعة."], ["ليبطّئنّ", "يتباطأ في الخروج فلا يخرج."], ["مصيبة", "قتل أو جراحات وهزيمة."], ["شهيداً", "حاضراً الغزوة معهم."], ["فضل", "نصر وغنيمة."], ["مودة", "صحبة ومعرفة مستلزمة للمودة."], ["فوزاً عظيماً", "نجاة من معرّة التخلّف عن الجهاد، والظفر بالسلامة والغنيمة."]], "m": "ينادي الله المؤمنين، وهم يستعدون لفتح مكة: خذوا الأهبة والاستعداد حتى لا تلاقوا عدوكم وأنتم ضعفاء، فانفروا جماعة بعد جماعة، أو انفروا جميعاً بقيادتكم، بحسب ما يتطلبه الموقف وتراه القيادة. ثم أخبرهم أن من عدادهم لمن يتباطأ عن الخروج ويبطّئ غيره، لأنه منافق لا يريد لكم نصراً، وكشف حاله: فإن أصابتكم مصيبة من قتل أو جراح أو هزيمة قال فرحاً بنجاته: قد أنعم الله عليّ إذ لم أكن معهم حاضراً، ولئن أصابكم فضل من الله بنصر وغنيمة ليقولنّ، كأن لم تكن بينكم وبينه معرفة ولا صلة، متمنياً حاسداً: يا ليتني كنت معهم فأفوز فوزاً عظيماً بالغنائم والعودة سالماً.", "h": ["وجوب أخذ الأهبة والاستعداد التام على أمة الإسلام، في السلم والحرب سواء.", "وجوب وجود خبرة عسكرية كاملة، وقيادة رشيدة مؤمنة حكيمة عليمة.", "وجود منهزمين روحياً مبطّئين حسدة بين المسلمين، وهم ضعاف الإيمان، فلا يُؤبه لهم ولا يُلتفت إليهم."], "k": "هل أفرح لإخواني إذا أصابهم خير، أم أنظر إلى نصيبي أنا فقط؟"}, {"lbl": "الآيات ٧٤ – ٧٦", "q": "۞فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا ﴿٧٤﴾ وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا ﴿٧٥﴾ ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّـٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا ﴿٧٦﴾", "w": [["سبيل الله", "الطريق الموصلة إلى إعلاء كلمة الله بأن يُعبد وحده."], ["يشرون", "يبيعون، إذ يُطلق الشراء على البيع أيضاً."], ["المستضعفين", "المستضعف: من قام به عجز فاستضعفه غيره فآذاه لضعفه."], ["القرية", "المدينة الكبيرة الجامعة، والمراد بها هنا مكة."], ["في سبيل الطاغوت", "في نصرة الشرك ومساندة الظلم والعدوان ونشر الفساد."]], "m": "بعد أن أمر الله المؤمنين بأخذ حذرهم، أمرهم أن يقاتلوا: فليقاتل في سبيل الله الذين يبيعون الحياة الدنيا بالآخرة، وهم المؤمنون حقاً، يقدّمون أموالهم وأرواحهم طلباً للفوز بالدار الآخرة، ومن يقاتل في سبيل الله فيُستشهد أو يغلب فسوف يؤتيه الله أجراً عظيماً: النجاة من النار ودخول الجنة. ثم استحثّهم: وما لكم لا تقاتلون في سبيل الله، ليُعبد وحده ويعزّ أولياؤه، وفي سبيل المستضعفين من الرجال والنساء والولدان الذين يضطهدهم المشركون ويعذّبونهم من أجل دينهم، حتى جأروا بالدعاء: ربنا أخرجنا من هذه القرية الظالم أهلها، واجعل لنا من لدنك ولياً يلي أمرنا، واجعل لنا من لدنك نصيراً. ثم قال: الذين آمنوا يقاتلون في سبيل الله لأنهم يؤمنون به وبوعده، والذين كفروا يقاتلون في سبيل الطاغوت، فقاتلوا أولياء الشيطان ولا ترهبوهم، إن كيد الشيطان كان ضعيفاً، فلا يثبت هو وأولياؤه أمام جيش الإيمان.", "h": ["فرضية القتال في سبيل الله، ولأجل إنقاذ المستضعفين من المؤمنين، نصرةً للحق وإبطالاً للباطل.", "المقاتل في سبيل الله باع دنياه واعتاض عنها الآخرة، ولنعم البيع.", "المجاهد يؤوب بأعظم صفقة، سواء قُتل أو انتصر وغلب، وهي الجنة.", "لا يمنع المؤمنين من الجهاد خوفُ أعدائهم؛ لأن قوتهم من قوة الشيطان، وكيده ضعيف."], "k": "«ربنا أخرجنا من هذه القرية الظالم أهلها»… هل أتذكر المستضعفين من المسلمين في دعائي؟"}, {"lbl": "الآيات ٧٧ – ٧٩", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا ﴿٧٧﴾ أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَـٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا ﴿٧٨﴾ مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا ﴿٧٩﴾", "w": [["كفّوا أيديكم", "عن القتال."], ["لولا أخّرتنا", "هلّا أخّرتنا."], ["فتيلاً", "الفتيل: خيط يكون في وسط النواة."], ["بروج مشيّدة", "حصون مشيّدة بالشِّيد، وهو الجص."], ["حسنة", "الحسنة ما سرّ، والسيئة ما ضرّ."]], "m": "رُوي أن بعض أصحاب رسول الله ﷺ طالبوا بالإذن لهم بالقتال ولم يؤذن لهم لعدم توفّر أسبابه، فكانوا يؤمرون بإقام الصلاة وإيتاء الزكاة، فلما فُرض القتال جبن فريق منهم وقالوا: ربنا لم كتبت علينا القتال، لولا أخّرتنا إلى أجل قريب، متعلّلين بعلل واهية، يريدون أن يدافعوا الأيام حتى يموتوا ولم يلقوا عدواً. فأمر الله رسوله أن يقول لهم: متاع الدنيا قليل مهما طابت الحياة، والآخرة خير لمن اتقى، ولا تُظلمون فتيلاً. ثم قال لهم ولغيرهم ممن يجبنون عن الجهاد: أينما تكونوا يدرككم الموت ولو كنتم في حصون مشيّدة. ثم ذكر سوء فهمهم: إن تصبهم حسنة من غنيمة أو خصب قالوا: هذه من عند الله، لا شكراً لله، وإنما كيلا ينسبوا إلى رسول الله ﷺ خيراً، وإن تصبهم سيئة من فقر أو مرض أو هزيمة قالوا: هذه من عندك، أي أنت السبب. قل كلٌّ من عند الله، هو الخالق والواضع لسنن حصولها، فما لهؤلاء لا يكادون يفقهون حديثاً؟ ثم خاطب رسوله ﷺ: ما أصابك من حسنة فمن الله، إذ هو الآمر بها والموجد لأسبابها والموفّق إليها، وما أصابك من سيئة فمن نفسك، إذ هي التي تأمر بها وتباشرها مخالفةً أمر الله، وأرسلناك للناس رسولاً، وقد أدّيت الرسالة، وكفى بالله شهيداً.", "h": ["قبح الاستعجال والجبن، وسوء عاقبتهما.", "الآخرة خير لمن اتقى من الدنيا.", "لا مفرّ من الموت ولا مهرب منه بحال من الأحوال.", "الخير والشر كلاهما بتقدير الله تعالى.", "الحسنة من الله؛ إذ أمر بأسبابها وأعان عليها وأبعد الموانع عنها، والسيئة من النفس؛ لأن الله نهى عنها وتوعّد على فعلها ولم يوفّق إليها."], "k": "«وما أصابك من سيئة فمن نفسك»… حين يصيبني سوء، هل أراجع نفسي أولاً أم ألوم غيري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 73;
insert into public.tdb_cards(topic, i, body) select 73, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧١ – ٧٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعٗا ﴿٧١﴾ وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ فَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةٞ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِيدٗا ﴿٧٢﴾ وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِيمٗا ﴿٧٣﴾", "w": [["خذوا حذركم", "الحذر: الاحتراس والاستعداد لدفع المكروه بحسبه."], ["فانفروا ثُبات", "النفور: الخروج في اندفاع، والثُّبات: جمع ثُبة، وهي الجماعة."], ["ليبطّئنّ", "يتباطأ في الخروج فلا يخرج."], ["مصيبة", "قتل أو جراحات وهزيمة."], ["شهيداً", "حاضراً الغزوة معهم."], ["فضل", "نصر وغنيمة."], ["مودة", "صحبة ومعرفة مستلزمة للمودة."], ["فوزاً عظيماً", "نجاة من معرّة التخلّف عن الجهاد، والظفر بالسلامة والغنيمة."]], "m": "ينادي الله المؤمنين، وهم يستعدون لفتح مكة: خذوا الأهبة والاستعداد حتى لا تلاقوا عدوكم وأنتم ضعفاء، فانفروا جماعة بعد جماعة، أو انفروا جميعاً بقيادتكم، بحسب ما يتطلبه الموقف وتراه القيادة. ثم أخبرهم أن من عدادهم لمن يتباطأ عن الخروج ويبطّئ غيره، لأنه منافق لا يريد لكم نصراً، وكشف حاله: فإن أصابتكم مصيبة من قتل أو جراح أو هزيمة قال فرحاً بنجاته: قد أنعم الله عليّ إذ لم أكن معهم حاضراً، ولئن أصابكم فضل من الله بنصر وغنيمة ليقولنّ، كأن لم تكن بينكم وبينه معرفة ولا صلة، متمنياً حاسداً: يا ليتني كنت معهم فأفوز فوزاً عظيماً بالغنائم والعودة سالماً.", "h": ["وجوب أخذ الأهبة والاستعداد التام على أمة الإسلام، في السلم والحرب سواء.", "وجوب وجود خبرة عسكرية كاملة، وقيادة رشيدة مؤمنة حكيمة عليمة.", "وجود منهزمين روحياً مبطّئين حسدة بين المسلمين، وهم ضعاف الإيمان، فلا يُؤبه لهم ولا يُلتفت إليهم."], "k": "هل أفرح لإخواني إذا أصابهم خير، أم أنظر إلى نصيبي أنا فقط؟"}, {"lbl": "الآيات ٧٤ – ٧٦", "q": "۞فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا ﴿٧٤﴾ وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا ﴿٧٥﴾ ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّـٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا ﴿٧٦﴾", "w": [["سبيل الله", "الطريق الموصلة إلى إعلاء كلمة الله بأن يُعبد وحده."], ["يشرون", "يبيعون، إذ يُطلق الشراء على البيع أيضاً."], ["المستضعفين", "المستضعف: من قام به عجز فاستضعفه غيره فآذاه لضعفه."], ["القرية", "المدينة الكبيرة الجامعة، والمراد بها هنا مكة."], ["في سبيل الطاغوت", "في نصرة الشرك ومساندة الظلم والعدوان ونشر الفساد."]], "m": "بعد أن أمر الله المؤمنين بأخذ حذرهم، أمرهم أن يقاتلوا: فليقاتل في سبيل الله الذين يبيعون الحياة الدنيا بالآخرة، وهم المؤمنون حقاً، يقدّمون أموالهم وأرواحهم طلباً للفوز بالدار الآخرة، ومن يقاتل في سبيل الله فيُستشهد أو يغلب فسوف يؤتيه الله أجراً عظيماً: النجاة من النار ودخول الجنة. ثم استحثّهم: وما لكم لا تقاتلون في سبيل الله، ليُعبد وحده ويعزّ أولياؤه، وفي سبيل المستضعفين من الرجال والنساء والولدان الذين يضطهدهم المشركون ويعذّبونهم من أجل دينهم، حتى جأروا بالدعاء: ربنا أخرجنا من هذه القرية الظالم أهلها، واجعل لنا من لدنك ولياً يلي أمرنا، واجعل لنا من لدنك نصيراً. ثم قال: الذين آمنوا يقاتلون في سبيل الله لأنهم يؤمنون به وبوعده، والذين كفروا يقاتلون في سبيل الطاغوت، فقاتلوا أولياء الشيطان ولا ترهبوهم، إن كيد الشيطان كان ضعيفاً، فلا يثبت هو وأولياؤه أمام جيش الإيمان.", "h": ["فرضية القتال في سبيل الله، ولأجل إنقاذ المستضعفين من المؤمنين، نصرةً للحق وإبطالاً للباطل.", "المقاتل في سبيل الله باع دنياه واعتاض عنها الآخرة، ولنعم البيع.", "المجاهد يؤوب بأعظم صفقة، سواء قُتل أو انتصر وغلب، وهي الجنة.", "لا يمنع المؤمنين من الجهاد خوفُ أعدائهم؛ لأن قوتهم من قوة الشيطان، وكيده ضعيف."], "k": "«ربنا أخرجنا من هذه القرية الظالم أهلها»… هل أتذكر المستضعفين من المسلمين في دعائي؟"}, {"lbl": "الآيات ٧٧ – ٧٩", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا ﴿٧٧﴾ أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَـٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا ﴿٧٨﴾ مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا ﴿٧٩﴾", "w": [["كفّوا أيديكم", "عن القتال."], ["لولا أخّرتنا", "هلّا أخّرتنا."], ["فتيلاً", "الفتيل: خيط يكون في وسط النواة."], ["بروج مشيّدة", "حصون مشيّدة بالشِّيد، وهو الجص."], ["حسنة", "الحسنة ما سرّ، والسيئة ما ضرّ."]], "m": "رُوي أن بعض أصحاب رسول الله ﷺ طالبوا بالإذن لهم بالقتال ولم يؤذن لهم لعدم توفّر أسبابه، فكانوا يؤمرون بإقام الصلاة وإيتاء الزكاة، فلما فُرض القتال جبن فريق منهم وقالوا: ربنا لم كتبت علينا القتال، لولا أخّرتنا إلى أجل قريب، متعلّلين بعلل واهية، يريدون أن يدافعوا الأيام حتى يموتوا ولم يلقوا عدواً. فأمر الله رسوله أن يقول لهم: متاع الدنيا قليل مهما طابت الحياة، والآخرة خير لمن اتقى، ولا تُظلمون فتيلاً. ثم قال لهم ولغيرهم ممن يجبنون عن الجهاد: أينما تكونوا يدرككم الموت ولو كنتم في حصون مشيّدة. ثم ذكر سوء فهمهم: إن تصبهم حسنة من غنيمة أو خصب قالوا: هذه من عند الله، لا شكراً لله، وإنما كيلا ينسبوا إلى رسول الله ﷺ خيراً، وإن تصبهم سيئة من فقر أو مرض أو هزيمة قالوا: هذه من عندك، أي أنت السبب. قل كلٌّ من عند الله، هو الخالق والواضع لسنن حصولها، فما لهؤلاء لا يكادون يفقهون حديثاً؟ ثم خاطب رسوله ﷺ: ما أصابك من حسنة فمن الله، إذ هو الآمر بها والموجد لأسبابها والموفّق إليها، وما أصابك من سيئة فمن نفسك، إذ هي التي تأمر بها وتباشرها مخالفةً أمر الله، وأرسلناك للناس رسولاً، وقد أدّيت الرسالة، وكفى بالله شهيداً.", "h": ["قبح الاستعجال والجبن، وسوء عاقبتهما.", "الآخرة خير لمن اتقى من الدنيا.", "لا مفرّ من الموت ولا مهرب منه بحال من الأحوال.", "الخير والشر كلاهما بتقدير الله تعالى.", "الحسنة من الله؛ إذ أمر بأسبابها وأعان عليها وأبعد الموانع عنها، والسيئة من النفس؛ لأن الله نهى عنها وتوعّد على فعلها ولم يوفّق إليها."], "k": "«وما أصابك من سيئة فمن نفسك»… حين يصيبني سوء، هل أراجع نفسي أولاً أم ألوم غيري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (74, 4, 80, 94, 'سورة النساء ٨٠ – ٩٤', 'أفلا يتدبرون القرآن، والشفاعة والتحية، وحرمة دم المؤمن', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 74) = $j$[{"lbl": "الآيات ٨٠ – ٨٣", "q": "مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا ﴿٨٠﴾ وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ مَا يُبَيِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿٨١﴾ أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا ﴿٨٢﴾ وَإِذَا جَآءَهُمۡ أَمۡرٞ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا ﴿٨٣﴾", "w": [["حفيظاً", "تحفظ عليهم أعمالهم وتحاسبهم عليها."], ["طاعة", "أمرنا طاعة لك."], ["برزوا", "خرجوا."], ["أفلا يتدبرون", "تدبّر القرآن: قراءة الآية أو الآيات وإعادتها المرة بعد المرة ليفقه مراد الله منها."], ["أذاعوا به", "أفشوه معلنين له للناس."], ["يستنبطونه", "يستخرجون معناه الصحيح."]], "m": "في قوله: «من يطع الرسول فقد أطاع الله» إنذار للناس كافة أن من لم يطع الرسول ﷺ ما أطاع الله، إذ أمره من أمر الله ونهيه من نهي الله، ومن تولّى عن طاعتك فدعه، فما أرسلناك عليهم حفيظاً تحصي أعمالهم، إن عليك إلا البلاغ. ويقول أولئك المنافقون: أمرنا طاعة، فإذا خرجوا من مجلسك دبّر طائفة منهم ليلاً غير الذي تقول، والله يكتب ما يبيّتون، فأعرض عنهم وتوكل على الله، وكفى بالله وكيلاً. ثم وبّخهم: أفلا يتدبرون القرآن؟ لو تدبّروه وهو يُتلى عليهم صباح مساء لعرفوا أن الرسول حق وأن ما جاء به حق، إذ لو كان كلام بشر لوجدوا فيه اختلافاً كثيراً، ولكنه كلام خالق البشر، متّسق الكلم، متآلف الألفاظ والمعاني. ثم نعى عليهم إرجافهم: إذا جاءهم خبر من سرايا الجهاد بنصر أو هزيمة سارعوا بإذاعته، حسداً أو فزعاً، ولو ردّوه إلى الرسول وإلى أمراء السرايا لعلمه الذين يستخرجون سرّه ويعرفون ما يترتب عليه، فإن كان نافعاً أذاعوه، وإن كان ضاراً أخفوه. ولولا فضل الله عليكم ورحمته لاتّبعتم الشيطان في قبول تلك الإشاعات إلا قليلاً من ذوي الآراء الصائبة.", "h": ["وجوب طاعة الرسول ﷺ، فإنه لا يُطاع لذاته، وإنما يُطاع لله عز وجل.", "وجوب تدبّر القرآن لتقوية الإيمان.", "آية أن القرآن وحي الله وكلامه: سلامته من التناقض والتضاد في الألفاظ والمعاني.", "تقرير مبدأ أن أخبار الحرب لا تُذاع إلا من قِبل القيادة العليا، حتى لا يقع الاضطراب في صفوف المجاهدين والأمة.", "أكثر الناس يتأثرون بما يسمعون، إلا القليل من ذوي الحصافة العقلية والوعي."], "k": "«أفلا يتدبرون القرآن»… ما الآية التي أكرّرها اليوم حتى أفهم مراد الله منها؟ وهل أتثبّت قبل أن أنشر خبراً؟"}, {"lbl": "الآيات ٨٤ – ٨٦", "q": "فَقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ وَٱللَّهُ أَشَدُّ بَأۡسٗا وَأَشَدُّ تَنكِيلٗا ﴿٨٤﴾ مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا ﴿٨٥﴾ وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا ﴿٨٦﴾", "w": [["حرّض المؤمنين", "حُثّهم على الجهاد ورغّبهم في القتال."], ["بأس الذين كفروا", "قوتهم الحربية."], ["وأشدّ تنكيلاً", "التنكيل: ضرب الظالم بقوة حتى يكون عبرة لمثله."], ["الشفاعة", "الوساطة في الخير أو في الشر، فإن كانت في الخير فهي الحسنة، وإن كانت في الشر فهي السيئة."], ["كِفل منها", "نصيب منها."], ["مقيتاً", "مقتدراً عليه، شاهداً عليه، حافظاً له."], ["بتحية", "تحية الإسلام: السلام عليكم ورحمة الله وبركاته."], ["أو ردّوها", "أي يقول: وعليكم السلام."], ["حسيباً", "محاسباً على العمل، مجازياً به خيراً كان أو شراً."]], "m": "ما زال السياق في السياسة الحربية، فأمر الله رسوله ﷺ أن يقاتل المشركين لإعلاء كلمة الله، لا يكلّفه ربه إلا نفسه وحدها، وأن يحرّض المؤمنين على القتال معه ويرغّبهم فيه، عسى الله أن يكفّ بأس الذين كفروا، وقد فعل وله الحمد، والله أشد بأساً وأشد تنكيلاً. ثم أخبر أن من يشفع شفاعة حسنة، بأن يضمّ صوته إلى مطالب بحق، أو يتوسّط لأحد في قضاء حاجته، فله نصيب من الأجر، ومن يشفع شفاعة سيئة بأن يؤيّد باطلاً أو يتوسط في شر أو ترك معروف فعليه نصيب من الوزر، وكان الله على كل شيء مقيتاً. ثم أمر المؤمنين أن يردّوا التحية بأحسن منها أو بمثلها: فمن قال: السلام عليكم، فليقل الرادّ: وعليكم السلام ورحمة الله، ومن قال: السلام عليكم ورحمة الله، فليقل: وعليكم السلام ورحمة الله وبركاته، إن الله كان على كل شيء حسيباً، يثيب المحسنين على إحسانهم.", "h": ["بيان شجاعة النبي ﷺ، بدليل أنه كُلّف بالقتال وحده.", "ليس من حق الحاكم أن يجنّد المواطنين تجنيداً إجبارياً، وإنما عليه أن يحضّهم على التجنيد ويرغّبهم فيه.", "فضل الشفاعة في الخير، وقبح الشفاعة في الشر.", "تأكيد سنة التحية، ووجوب ردّها بأحسن منها أو بمثلها.", "تقرير ما جاء في السنة: أن «السلام عليكم» يُعطى عليها المسلم عشر حسنات، و«ورحمة الله» عشراً، و«وبركاته» عشراً كذلك."], "k": "هل أستطيع اليوم أن أشفع شفاعة حسنة لأحد؟ وهل أردّ السلام بأحسن منه؟"}, {"lbl": "الآيات ٨٧ – ٩١", "q": "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا ﴿٨٧﴾ ۞فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا ﴿٨٨﴾ وَدُّواْ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ حَتَّىٰ يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا ﴿٨٩﴾ إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ وَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلٗا ﴿٩٠﴾ سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ مَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ إِلَيۡكُمُ ٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُوْلَـٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنٗا مُّبِينٗا ﴿٩١﴾", "w": [["لا إله إلا هو", "لا معبود بحق إلا هو."], ["فئتين", "جماعتين."], ["أركسهم", "الارتكاس: التحوّل من حال حسنة إلى حال سيئة كالكفر بعد الإيمان، أو الغدر بعد الأمان."], ["سبيلاً", "طريقاً إلى هدايتهم."], ["ولياً ولا نصيراً", "الولي: من يلي أمرك، والنصير: من ينصرك على عدوك."], ["يصلون", "يتّصلون بهم بموجب عقد معاهدة بينهم."], ["ميثاق", "عهد."], ["حصرت صدورهم", "ضاقت."], ["السلم", "الاستسلام والانقياد."], ["الفتنة", "الشرك."], ["ثقفتموهم", "وجدتموهم متمكّنين منهم."], ["سلطاناً مبيناً", "حجة بيّنة على جواز قتالهم."]], "m": "لما ذكر الله أنه المقيت الحسيب، أخبر أنه الله الذي لا إله إلا هو، ليجمعنّكم إلى يوم القيامة لا ريب فيه، ومن أصدق من الله حديثاً؟ أما الآيات الأربع بعدها فنزلت في اختلاف الصحابة في طائفة من المنافقين أظهروا الإسلام وهم ضالعون في موالاة الكافرين، فرأى بعضهم الضرب على أيديهم، ورأى آخرون الصبر عليهم لعلهم يتوبون، فقال تعالى: ما لكم في المنافقين فئتين، والله قد ردّهم إلى الكفر بما كسبوا؟ أتريدون أن تهدوا من أضلّ الله؟ ومن يضلل الله فلن تجد له سبيلاً. ودّوا لو تكفرون كما كفروا فتكونون سواء، فلا تتخذوا منهم أولياء حتى يهاجروا في سبيل الله، فإن تولّوا فخذوهم واقتلوهم حيث وجدتموهم. واستثنى صنفين: الذين يلجؤون إلى قوم بينكم وبينهم ميثاق، والذين ضاقت صدورهم أن يقاتلوكم أو يقاتلوا قومهم، فإن اعتزلوكم وألقوا إليكم السلم فما جعل الله لكم عليهم سبيلاً. وصنفاً ثالثاً يريدون أن يأمنوكم ويأمنوا قومهم، كلما رُدّوا إلى الشرك وقعوا فيه، فإن لم يعتزلوكم ويكفّوا أيديهم فخذوهم واقتلوهم حيث ثقفتموهم. مع العلم أن الكفّ عن قتال المشركين قد نُسخ بآيات براءة، إلا أن لإمام المسلمين أن يأخذ بهذا النظام عند الحاجة.", "h": ["وجوب توحيد الله تعالى في عبادته.", "الإيمان بالبعث والجزاء.", "خطة حكيمة لمعاملة المنافقين بحسب الظروف والأحوال.", "تقرير النسخ في القرآن."], "k": "«ومن أصدق من الله حديثاً»… هل أثق بوعد الله أكثر مما أثق بحساباتي؟"}, {"lbl": "الآيتان ٩٢ – ٩٣", "q": "وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿٩٢﴾ وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا ﴿٩٣﴾", "w": [["إلا خطأً", "إلا قتلاً خطأً، وهو ألا يتعمّد قتله، كأن يرمي صيداً فيصيب إنساناً."], ["رقبة", "مملوك، عبداً كان أو أمة."], ["مسلّمة", "مؤدّاة وافية."], ["إلا أن يصّدّقوا", "يتصدّقوا بها على القاتل فلا يطالبوا بها."], ["ميثاق", "عهد مؤكد بالأيمان."], ["متعمّداً", "مريداً قتله وهو ظالم له."]], "m": "لما ذكر الله قتال المنافقين متى يجوز ومتى لا يجوز، ناسب ذكر قتل المؤمن الصادق خطأً وعمداً: فلا ينبغي لمؤمن أن يقتل مؤمناً إلا خطأً، أما العمد فلا يتأتّى منه وهو مؤمن؛ لأن الإيمان نور يكشف قبح هذه الجريمة وما وراءها من غضب الله. وحكم من قتل خطأً أن يعتق رقبة مؤمنة، وأن يدفع الدية إلى أولياء القتيل إلا أن يتصدّقوا بها، والدية مائة من الإبل، أو ألف دينار ذهباً، أو اثنا عشر ألف درهم فضة. فإن كان القتيل مؤمناً من قوم محاربين للمسلمين فالواجب تحرير رقبة مؤمنة لا غير، إذ لا تُعطى الدية لعدو يستعين بها على حرب المسلمين، وإن كان من قوم بيننا وبينهم معاهدة فعلى القاتل الدية وتحرير رقبة، فمن لم يجد الرقبة صام شهرين متتابعين، توبةً من الله، وكان الله عليماً حكيماً. ثم بيّن حكم من قتل مؤمناً عمداً عدواناً: أن الكفارة لا تغني عنه شيئاً، فجزاؤه جهنم خالداً فيها، وغضب الله عليه ولعنه وأعدّ له عذاباً عظيماً، مع لزوم القصاص أو الدية ما لم يعفُ أولياء الدم؛ فالقتيل عبد الله خلقه ليعبده، فمن قتله فالله ربُّ العبد خصمه.", "h": ["بيان أن المؤمن الحق لا يقع منه القتل العمد للمؤمن.", "بيان جزاء القتل الخطأ، وهو تحرير رقبة ودية مسلّمة إلى أهله.", "إذا كان القتيل مؤمناً من قوم كافرين محاربين فالجزاء تحرير رقبة، ولا دية.", "إذا كان القتيل من قوم بين المسلمين وبينهم ميثاق فالواجب الدية وتحرير رقبة.", "القتل العمد العدوان يجب له أحد شيئين: القصاص أو الدية، حسب رغبة أولياء الدم، وإن عفوا فلهم ذلك وأجرهم على الله، وعذاب الآخرة وعيد إن شاء الله أنجزه."], "k": "حرمة دم المسلم عند الله بهذا القدر… فهل أحفظ حرمة عرضه وماله ومشاعره كذلك؟"}, {"lbl": "الآية ٩٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا تَبۡتَغُونَ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٞۚ كَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ فَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿٩٤﴾", "w": [["إذا ضربتم", "خرجتم تضربون الأرض بأرجلكم غزاةً ومسافرين."], ["فتبيّنوا", "فتثبّتوا حتى لا تقتلوا مسلماً تحسبونه كافراً."], ["السلم", "الاستسلام والانقياد."], ["تبتغون", "تطلبون."], ["منّ الله عليكم", "بالهداية فاهتديتم وأصبحتم مسلمين."]], "m": "رُوي أن نفراً من أصحاب رسول الله ﷺ خرجوا فلقوا رجلاً من بني سليم يسوق غنماً، فلما رآهم سلّم عليهم، فقالوا: ما قلتها إلا تقيّة لتحفظ نفسك ومالك، فقتلوه، فنزلت: يا أيها الذين آمنوا إذا خرجتم مسافرين للغزو فتبيّنوا من تلقونه في طريقكم، أمسلم هو فتكفّوا عنه، أم كافر فتقاتلوه؟ ولا تقولوا لمن أعلن إسلامه لكم بالشهادة أو بالسلام: لست مؤمناً، فتكذّبوه لتنالوا منه، تبتغون بذلك عرض الحياة الدنيا الزائل، فإن كان قصدكم الغنيمة فعند الله مغانم كثيرة، فأطيعوه. كذلك كنتم من قبل، فمنّ الله عليكم بالهداية، فتبيّنوا مستقبلاً، ولا تقتلوا أحداً حتى تتأكدوا من كفره، إن الله كان بما تعملون خبيراً، وعداً لمن أطاع ووعيداً لمن عصى.", "h": ["مشروعية السير في سبيل الله غزواً وجهاداً.", "وجوب التثبّت والتبيّن في الأمور التي يترتب على الخطأ فيها ضرر بالغ.", "ذم الرغبة في الدنيا، لا سيما إذا كانت تتعارض مع التقوى.", "الاتعاظ بحال الغير، والاعتبار بالأحداث الماثلة."], "k": "«فتبيّنوا»… كم مرة حكمتُ على نية إنسان دون أن أتثبّت؟"}]$j$::jsonb then 0 else 1 end;
