insert into public.tdb_cards(topic, i, body) select 74, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٠ – ٨٣", "q": "مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا ﴿٨٠﴾ وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ مَا يُبَيِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿٨١﴾ أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا ﴿٨٢﴾ وَإِذَا جَآءَهُمۡ أَمۡرٞ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا ﴿٨٣﴾", "w": [["حفيظاً", "تحفظ عليهم أعمالهم وتحاسبهم عليها."], ["طاعة", "أمرنا طاعة لك."], ["برزوا", "خرجوا."], ["أفلا يتدبرون", "تدبّر القرآن: قراءة الآية أو الآيات وإعادتها المرة بعد المرة ليفقه مراد الله منها."], ["أذاعوا به", "أفشوه معلنين له للناس."], ["يستنبطونه", "يستخرجون معناه الصحيح."]], "m": "في قوله: «من يطع الرسول فقد أطاع الله» إنذار للناس كافة أن من لم يطع الرسول ﷺ ما أطاع الله، إذ أمره من أمر الله ونهيه من نهي الله، ومن تولّى عن طاعتك فدعه، فما أرسلناك عليهم حفيظاً تحصي أعمالهم، إن عليك إلا البلاغ. ويقول أولئك المنافقون: أمرنا طاعة، فإذا خرجوا من مجلسك دبّر طائفة منهم ليلاً غير الذي تقول، والله يكتب ما يبيّتون، فأعرض عنهم وتوكل على الله، وكفى بالله وكيلاً. ثم وبّخهم: أفلا يتدبرون القرآن؟ لو تدبّروه وهو يُتلى عليهم صباح مساء لعرفوا أن الرسول حق وأن ما جاء به حق، إذ لو كان كلام بشر لوجدوا فيه اختلافاً كثيراً، ولكنه كلام خالق البشر، متّسق الكلم، متآلف الألفاظ والمعاني. ثم نعى عليهم إرجافهم: إذا جاءهم خبر من سرايا الجهاد بنصر أو هزيمة سارعوا بإذاعته، حسداً أو فزعاً، ولو ردّوه إلى الرسول وإلى أمراء السرايا لعلمه الذين يستخرجون سرّه ويعرفون ما يترتب عليه، فإن كان نافعاً أذاعوه، وإن كان ضاراً أخفوه. ولولا فضل الله عليكم ورحمته لاتّبعتم الشيطان في قبول تلك الإشاعات إلا قليلاً من ذوي الآراء الصائبة.", "h": ["وجوب طاعة الرسول ﷺ، فإنه لا يُطاع لذاته، وإنما يُطاع لله عز وجل.", "وجوب تدبّر القرآن لتقوية الإيمان.", "آية أن القرآن وحي الله وكلامه: سلامته من التناقض والتضاد في الألفاظ والمعاني.", "تقرير مبدأ أن أخبار الحرب لا تُذاع إلا من قِبل القيادة العليا، حتى لا يقع الاضطراب في صفوف المجاهدين والأمة.", "أكثر الناس يتأثرون بما يسمعون، إلا القليل من ذوي الحصافة العقلية والوعي."], "k": "«أفلا يتدبرون القرآن»… ما الآية التي أكرّرها اليوم حتى أفهم مراد الله منها؟ وهل أتثبّت قبل أن أنشر خبراً؟"}, {"lbl": "الآيات ٨٤ – ٨٦", "q": "فَقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ وَٱللَّهُ أَشَدُّ بَأۡسٗا وَأَشَدُّ تَنكِيلٗا ﴿٨٤﴾ مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا ﴿٨٥﴾ وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا ﴿٨٦﴾", "w": [["حرّض المؤمنين", "حُثّهم على الجهاد ورغّبهم في القتال."], ["بأس الذين كفروا", "قوتهم الحربية."], ["وأشدّ تنكيلاً", "التنكيل: ضرب الظالم بقوة حتى يكون عبرة لمثله."], ["الشفاعة", "الوساطة في الخير أو في الشر، فإن كانت في الخير فهي الحسنة، وإن كانت في الشر فهي السيئة."], ["كِفل منها", "نصيب منها."], ["مقيتاً", "مقتدراً عليه، شاهداً عليه، حافظاً له."], ["بتحية", "تحية الإسلام: السلام عليكم ورحمة الله وبركاته."], ["أو ردّوها", "أي يقول: وعليكم السلام."], ["حسيباً", "محاسباً على العمل، مجازياً به خيراً كان أو شراً."]], "m": "ما زال السياق في السياسة الحربية، فأمر الله رسوله ﷺ أن يقاتل المشركين لإعلاء كلمة الله، لا يكلّفه ربه إلا نفسه وحدها، وأن يحرّض المؤمنين على القتال معه ويرغّبهم فيه، عسى الله أن يكفّ بأس الذين كفروا، وقد فعل وله الحمد، والله أشد بأساً وأشد تنكيلاً. ثم أخبر أن من يشفع شفاعة حسنة، بأن يضمّ صوته إلى مطالب بحق، أو يتوسّط لأحد في قضاء حاجته، فله نصيب من الأجر، ومن يشفع شفاعة سيئة بأن يؤيّد باطلاً أو يتوسط في شر أو ترك معروف فعليه نصيب من الوزر، وكان الله على كل شيء مقيتاً. ثم أمر المؤمنين أن يردّوا التحية بأحسن منها أو بمثلها: فمن قال: السلام عليكم، فليقل الرادّ: وعليكم السلام ورحمة الله، ومن قال: السلام عليكم ورحمة الله، فليقل: وعليكم السلام ورحمة الله وبركاته، إن الله كان على كل شيء حسيباً، يثيب المحسنين على إحسانهم.", "h": ["بيان شجاعة النبي ﷺ، بدليل أنه كُلّف بالقتال وحده.", "ليس من حق الحاكم أن يجنّد المواطنين تجنيداً إجبارياً، وإنما عليه أن يحضّهم على التجنيد ويرغّبهم فيه.", "فضل الشفاعة في الخير، وقبح الشفاعة في الشر.", "تأكيد سنة التحية، ووجوب ردّها بأحسن منها أو بمثلها.", "تقرير ما جاء في السنة: أن «السلام عليكم» يُعطى عليها المسلم عشر حسنات، و«ورحمة الله» عشراً، و«وبركاته» عشراً كذلك."], "k": "هل أستطيع اليوم أن أشفع شفاعة حسنة لأحد؟ وهل أردّ السلام بأحسن منه؟"}, {"lbl": "الآيات ٨٧ – ٩١", "q": "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا ﴿٨٧﴾ ۞فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا ﴿٨٨﴾ وَدُّواْ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ حَتَّىٰ يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا ﴿٨٩﴾ إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ وَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلٗا ﴿٩٠﴾ سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ مَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ إِلَيۡكُمُ ٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُوْلَـٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنٗا مُّبِينٗا ﴿٩١﴾", "w": [["لا إله إلا هو", "لا معبود بحق إلا هو."], ["فئتين", "جماعتين."], ["أركسهم", "الارتكاس: التحوّل من حال حسنة إلى حال سيئة كالكفر بعد الإيمان، أو الغدر بعد الأمان."], ["سبيلاً", "طريقاً إلى هدايتهم."], ["ولياً ولا نصيراً", "الولي: من يلي أمرك، والنصير: من ينصرك على عدوك."], ["يصلون", "يتّصلون بهم بموجب عقد معاهدة بينهم."], ["ميثاق", "عهد."], ["حصرت صدورهم", "ضاقت."], ["السلم", "الاستسلام والانقياد."], ["الفتنة", "الشرك."], ["ثقفتموهم", "وجدتموهم متمكّنين منهم."], ["سلطاناً مبيناً", "حجة بيّنة على جواز قتالهم."]], "m": "لما ذكر الله أنه المقيت الحسيب، أخبر أنه الله الذي لا إله إلا هو، ليجمعنّكم إلى يوم القيامة لا ريب فيه، ومن أصدق من الله حديثاً؟ أما الآيات الأربع بعدها فنزلت في اختلاف الصحابة في طائفة من المنافقين أظهروا الإسلام وهم ضالعون في موالاة الكافرين، فرأى بعضهم الضرب على أيديهم، ورأى آخرون الصبر عليهم لعلهم يتوبون، فقال تعالى: ما لكم في المنافقين فئتين، والله قد ردّهم إلى الكفر بما كسبوا؟ أتريدون أن تهدوا من أضلّ الله؟ ومن يضلل الله فلن تجد له سبيلاً. ودّوا لو تكفرون كما كفروا فتكونون سواء، فلا تتخذوا منهم أولياء حتى يهاجروا في سبيل الله، فإن تولّوا فخذوهم واقتلوهم حيث وجدتموهم. واستثنى صنفين: الذين يلجؤون إلى قوم بينكم وبينهم ميثاق، والذين ضاقت صدورهم أن يقاتلوكم أو يقاتلوا قومهم، فإن اعتزلوكم وألقوا إليكم السلم فما جعل الله لكم عليهم سبيلاً. وصنفاً ثالثاً يريدون أن يأمنوكم ويأمنوا قومهم، كلما رُدّوا إلى الشرك وقعوا فيه، فإن لم يعتزلوكم ويكفّوا أيديهم فخذوهم واقتلوهم حيث ثقفتموهم. مع العلم أن الكفّ عن قتال المشركين قد نُسخ بآيات براءة، إلا أن لإمام المسلمين أن يأخذ بهذا النظام عند الحاجة.", "h": ["وجوب توحيد الله تعالى في عبادته.", "الإيمان بالبعث والجزاء.", "خطة حكيمة لمعاملة المنافقين بحسب الظروف والأحوال.", "تقرير النسخ في القرآن."], "k": "«ومن أصدق من الله حديثاً»… هل أثق بوعد الله أكثر مما أثق بحساباتي؟"}, {"lbl": "الآيتان ٩٢ – ٩٣", "q": "وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿٩٢﴾ وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا ﴿٩٣﴾", "w": [["إلا خطأً", "إلا قتلاً خطأً، وهو ألا يتعمّد قتله، كأن يرمي صيداً فيصيب إنساناً."], ["رقبة", "مملوك، عبداً كان أو أمة."], ["مسلّمة", "مؤدّاة وافية."], ["إلا أن يصّدّقوا", "يتصدّقوا بها على القاتل فلا يطالبوا بها."], ["ميثاق", "عهد مؤكد بالأيمان."], ["متعمّداً", "مريداً قتله وهو ظالم له."]], "m": "لما ذكر الله قتال المنافقين متى يجوز ومتى لا يجوز، ناسب ذكر قتل المؤمن الصادق خطأً وعمداً: فلا ينبغي لمؤمن أن يقتل مؤمناً إلا خطأً، أما العمد فلا يتأتّى منه وهو مؤمن؛ لأن الإيمان نور يكشف قبح هذه الجريمة وما وراءها من غضب الله. وحكم من قتل خطأً أن يعتق رقبة مؤمنة، وأن يدفع الدية إلى أولياء القتيل إلا أن يتصدّقوا بها، والدية مائة من الإبل، أو ألف دينار ذهباً، أو اثنا عشر ألف درهم فضة. فإن كان القتيل مؤمناً من قوم محاربين للمسلمين فالواجب تحرير رقبة مؤمنة لا غير، إذ لا تُعطى الدية لعدو يستعين بها على حرب المسلمين، وإن كان من قوم بيننا وبينهم معاهدة فعلى القاتل الدية وتحرير رقبة، فمن لم يجد الرقبة صام شهرين متتابعين، توبةً من الله، وكان الله عليماً حكيماً. ثم بيّن حكم من قتل مؤمناً عمداً عدواناً: أن الكفارة لا تغني عنه شيئاً، فجزاؤه جهنم خالداً فيها، وغضب الله عليه ولعنه وأعدّ له عذاباً عظيماً، مع لزوم القصاص أو الدية ما لم يعفُ أولياء الدم؛ فالقتيل عبد الله خلقه ليعبده، فمن قتله فالله ربُّ العبد خصمه.", "h": ["بيان أن المؤمن الحق لا يقع منه القتل العمد للمؤمن.", "بيان جزاء القتل الخطأ، وهو تحرير رقبة ودية مسلّمة إلى أهله.", "إذا كان القتيل مؤمناً من قوم كافرين محاربين فالجزاء تحرير رقبة، ولا دية.", "إذا كان القتيل من قوم بين المسلمين وبينهم ميثاق فالواجب الدية وتحرير رقبة.", "القتل العمد العدوان يجب له أحد شيئين: القصاص أو الدية، حسب رغبة أولياء الدم، وإن عفوا فلهم ذلك وأجرهم على الله، وعذاب الآخرة وعيد إن شاء الله أنجزه."], "k": "حرمة دم المسلم عند الله بهذا القدر… فهل أحفظ حرمة عرضه وماله ومشاعره كذلك؟"}, {"lbl": "الآية ٩٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا تَبۡتَغُونَ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٞۚ كَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ فَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿٩٤﴾", "w": [["إذا ضربتم", "خرجتم تضربون الأرض بأرجلكم غزاةً ومسافرين."], ["فتبيّنوا", "فتثبّتوا حتى لا تقتلوا مسلماً تحسبونه كافراً."], ["السلم", "الاستسلام والانقياد."], ["تبتغون", "تطلبون."], ["منّ الله عليكم", "بالهداية فاهتديتم وأصبحتم مسلمين."]], "m": "رُوي أن نفراً من أصحاب رسول الله ﷺ خرجوا فلقوا رجلاً من بني سليم يسوق غنماً، فلما رآهم سلّم عليهم، فقالوا: ما قلتها إلا تقيّة لتحفظ نفسك ومالك، فقتلوه، فنزلت: يا أيها الذين آمنوا إذا خرجتم مسافرين للغزو فتبيّنوا من تلقونه في طريقكم، أمسلم هو فتكفّوا عنه، أم كافر فتقاتلوه؟ ولا تقولوا لمن أعلن إسلامه لكم بالشهادة أو بالسلام: لست مؤمناً، فتكذّبوه لتنالوا منه، تبتغون بذلك عرض الحياة الدنيا الزائل، فإن كان قصدكم الغنيمة فعند الله مغانم كثيرة، فأطيعوه. كذلك كنتم من قبل، فمنّ الله عليكم بالهداية، فتبيّنوا مستقبلاً، ولا تقتلوا أحداً حتى تتأكدوا من كفره، إن الله كان بما تعملون خبيراً، وعداً لمن أطاع ووعيداً لمن عصى.", "h": ["مشروعية السير في سبيل الله غزواً وجهاداً.", "وجوب التثبّت والتبيّن في الأمور التي يترتب على الخطأ فيها ضرر بالغ.", "ذم الرغبة في الدنيا، لا سيما إذا كانت تتعارض مع التقوى.", "الاتعاظ بحال الغير، والاعتبار بالأحداث الماثلة."], "k": "«فتبيّنوا»… كم مرة حكمتُ على نية إنسان دون أن أتثبّت؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (75, 4, 95, 113, 'سورة النساء ٩٥ – ١١٣', 'فضل المجاهدين، والهجرة، وصلاة القصر والخوف، وقصة ابن أُبَيرق', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 75) = $j$[{"lbl": "الآيتان ٩٥ – ٩٦", "q": "لَّا يَسۡتَوِي ٱلۡقَٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِينَ غَيۡرُ أُوْلِي ٱلضَّرَرِ وَٱلۡمُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَٰعِدِينَ دَرَجَةٗۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمٗا ﴿٩٥﴾ دَرَجَٰتٖ مِّنۡهُ وَمَغۡفِرَةٗ وَرَحۡمَةٗۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا ﴿٩٦﴾", "w": [["أولو الضرر", "العميان والعرج والمرضى."], ["درجة", "منزلة عالية في الجنة."], ["الحسنى", "الجنة."]], "m": "رُوي أن ابن أم مكتوم رضي الله عنه لما نزلت الآية بصيغة: «لا يستوي القاعدون من المؤمنين والمجاهدون في سبيل الله بأموالهم وأنفسهم» أتى النبي ﷺ فقال: كيف وأنا أعمى يا رسول الله؟ فما برح حتى نزلت «غير أولي الضرر» فأُدخلت في الآية. فنفى الله أن يستوي في الأجر والمنزلة من يجاهد بماله ونفسه ومن لا يجاهد بخلاً بماله وضنّاً بنفسه، واستثنى أولي الأعذار من مرض ونحوه، فلهم أجر المجاهدين لحسن نياتهم وعدم استطاعتهم، وكلاً وعد الله الحسنى، وهي الجنة. وفضّل الله المجاهدين على القاعدين لعذر درجة، وفضّلهم على القاعدين لغير عذر أجراً عظيماً، درجات منه ومغفرة ورحمة، وكان الله غفوراً رحيماً، اللهم اغفر لنا وارحمنا معهم.", "h": ["بيان فضل المجاهدين على غيرهم من المؤمنين الذين لا يجاهدون.", "أصحاب الأعذار الشرعية ينالون أجر المجاهدين إن كانت لهم رغبة في الجهاد ولم يقدروا عليه لما قام بهم من أعذار، وللمجاهدين فعلاً درجة تخصّهم دون ذوي الأعذار."], "k": "هل لي نية صادقة في خير عجزت عنه؟ فالنية الصادقة تبلغ ما لا يبلغه العمل."}, {"lbl": "الآيات ٩٧ – ١٠٠", "q": "إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡ قَالُواْ فِيمَ كُنتُمۡۖ قَالُواْ كُنَّا مُسۡتَضۡعَفِينَ فِي ٱلۡأَرۡضِۚ قَالُوٓاْ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَٰسِعَةٗ فَتُهَاجِرُواْ فِيهَاۚ فَأُوْلَـٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا ﴿٩٧﴾ إِلَّا ٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ لَا يَسۡتَطِيعُونَ حِيلَةٗ وَلَا يَهۡتَدُونَ سَبِيلٗا ﴿٩٨﴾ فَأُوْلَـٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا ﴿٩٩﴾ ۞وَمَن يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمٗا كَثِيرٗا وَسَعَةٗۚ وَمَن يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿١٠٠﴾", "w": [["توفّاهم", "تقبض أرواحهم عند نهاية آجالهم."], ["ظالمي أنفسهم", "بتركهم الهجرة وقد وجبت عليهم."], ["فيمَ كنتم", "في أي شيء كنتم من دينكم؟"], ["مصيراً", "مأوى ومسكناً."], ["حيلة", "قدرة على التحوّل."], ["مراغماً", "مكاناً وداراً لهجرته يُرغم ويُذلّ به من كان يؤذيه في داره."], ["وسعة", "في رزقه."], ["وقع أجره على الله", "وجب أجره في هجرته على الله تعالى."]], "m": "لما كانت الهجرة من آثار الجهاد، ذكر الله القاعدين عنها: إن الذين تتوفّاهم الملائكة ظالمي أنفسهم، حيث تركوا الهجرة ومكثوا في دار الهوان يضطهدهم العدو ويحول بينهم وبين عبادة ربهم، تقول لهم الملائكة عند قبض أرواحهم: فيمَ كنتم؟ فيقولون معتذرين: كنا مستضعفين في الأرض، فتردّ عليهم: ألم تكن أرض الله واسعة فتهاجروا فيها وتعبدوا ربكم؟ فأولئك مأواهم جهنم وساءت مصيراً. ثم استثنى أصحاب الأعذار: المستضعفين من الرجال بالعلل، والنساء والولدان بالضعف الملازم لهم، لا يستطيعون حيلة ولا يهتدون سبيلاً إلى دار الهجرة، فأولئك عسى الله أن يعفو عنهم، وكان الله عفوّاً غفوراً. ثم أخبر أن من يهاجر في سبيل الله، لا في سبيل دنيا يصيبها أو امرأة يتزوّجها، يجد في الأرض مذهباً يذهب إليه وداراً ينزل بها ورزقاً واسعاً يُرغم به عدوه، ومن خرج من بيته مهاجراً إلى الله ورسوله ثم أدركه الموت في الطريق فقد وجب أجره على الله كاملاً، وكان الله غفوراً رحيماً.", "h": ["وجوب الهجرة عندما يُحال بين المؤمن وعبادة ربه تعالى، إذ لم يُخلق إلا لها.", "ترك الهجرة كبيرة من كبائر الذنوب، يستوجب صاحبها دخول النار.", "أصحاب الأعذار كما سقط عنهم واجب الجهاد يسقط عنهم واجب الهجرة.", "فضل الهجرة في سبيل الله تعالى.", "من مات في طريق هجرته أُعطي أجر المهاجر كاملاً غير منقوص، وهو الجنة."], "k": "«ومن يخرج من بيته مهاجراً إلى الله ورسوله»… ما العادة أو المكان الذي أحتاج أن «أهاجر» منه إلى الله؟"}, {"lbl": "الآيات ١٠١ – ١٠٤", "q": "وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا ﴿١٠١﴾ وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا ﴿١٠٢﴾ فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا ﴿١٠٣﴾ وَلَا تَهِنُواْ فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا ﴿١٠٤﴾", "w": [["ضربتم في الأرض", "سافرتم مسافة قصر، وهي أربعة بُرُد، أي ثمانية وأربعون ميلاً."], ["أن تقصروا من الصلاة", "بأن تصلّوا الظهر والعصر والعشاء ركعتين ركعتين."], ["إن خفتم أن يفتنكم", "خرج مخرج الغالب، فليس الخوف بشرط في القصر، وإنما الشرط السفر."], ["حذرهم", "الحيطة والأهبة لما عسى أن يحدث من العدو."], ["وأسلحتهم", "جمع سلاح، وهو ما يُقاتل به."], ["لا جناح عليكم", "لا حرج عليكم في وضع الأسلحة."], ["قضيتم الصلاة", "أدّيتموها وفرغتم منها."], ["فإذا اطمأننتم", "ذهب الخوف فحصلت الطمأنينة بالأمن."], ["كتاباً موقوتاً", "فرضاً ذا وقت معيّن تؤدّى فيه، لا تتقدّمه ولا تتأخر عنه."], ["ولا تهنوا", "لا تضعفوا."], ["تألمون", "تتألمون."]], "m": "بمناسبة الهجرة، والسفر من لوازمها، ذكر الله رخصة قصر الصلاة الرباعية إلى ركعتين في السفر، وبيّنت السنة أن المسافر يقصر ولو أمن، فقيد الخوف غالبيّ فقط. ثم بيّن صلاة الخوف: أن ينقسم الجيش قسمين، قسم يقف تجاه العدو وقسم يصلي مع القائد ركعة ثم يتمّون لأنفسهم ويقفون تجاه العدو، ويأتي القسم الآخر فيصلي بهم الإمام ركعة ويتمّون لأنفسهم، وهم في الحالين آخذون أسلحتهم، إذ ودّ الذين كفروا لو تغفلون عن أسلحتكم وأمتعتكم فيميلون عليكم ميلة واحدة، ورخّص لهم في وضعها إن كان بهم أذى من مطر أو مرض، مع أخذ الحذر. ثم أمرهم إذا قضوا الصلاة أن يذكروا الله قياماً وقعوداً وعلى جنوبهم، لاسيما عند لقاء العدو لما فيه من القوة الروحية، فإذا اطمأنّوا أقاموا الصلاة تامة بحدودها وأركانها، إن الصلاة كانت على المؤمنين فرضاً موقوتاً. ثم قال: ولا تضعفوا في طلب العدو، إن تكونوا تألمون لجراحاتكم فإنهم يألمون كما تألمون، وترجون من الله من النصر والمثوبة ما لا يرجون، فأنتم أحق بالصبر والجلد، وكان الله عليماً حكيماً.", "h": ["مشروعية صلاة القصر، وهي رخصة أكّدها رسول الله ﷺ بقوله وعمله فأصبحت سنة مؤكدة لا ينبغي تركها.", "مشروعية صلاة الخوف وبيان كيفيتها.", "تأكّد صلاة الجماعة، بحيث لا تُترك حتى في ساعة الخوف والقتال.", "استحباب ذكر الله تعالى بعد الصلاة وعلى كل حال، من قيام وقعود واضطجاع.", "تقرير فرضية الصلاة، ووجوب أدائها في أوقاتها الموقوتة لها.", "حرمة الوهن والضعف إزاء حرب العدو، والاستعانة على قتاله بذكر الله ورجائه."], "k": "لم تسقط الصلاة حتى في ساعة القتال… فما عذري حين أؤخّرها عن وقتها؟"}, {"lbl": "الآيات ١٠٥ – ١٠٩", "q": "إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَيۡنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا ﴿١٠٥﴾ وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ﴿١٠٦﴾ وَلَا تُجَٰدِلۡ عَنِ ٱلَّذِينَ يَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمٗا ﴿١٠٧﴾ يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا ﴿١٠٨﴾ هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ جَٰدَلۡتُمۡ عَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلٗا ﴿١٠٩﴾", "w": [["بما أراك الله", "بما علّمكه بواسطة الوحي."], ["خصيماً", "مخاصماً بالغاً في الخصومة مبلغاً عظيماً."], ["تجادل", "تخاصم."], ["يختانون أنفسهم", "يحاولون خيانة أنفسهم."], ["يستخفون", "يطلبون إخفاء أنفسهم عن الناس."], ["وهو معهم", "بعلمه تعالى وقدرته."], ["يبيّتون", "يدبّرون الأمر في خفاء ومكر وخديعة."], ["وكيلاً", "الوكيل: من ينوب عن آخر في تحقيق غرض من الأغراض."]], "m": "رُوي أن هذه الآيات نزلت في طعمة بن أُبَيرق وإخوته، وكان قد سرق درعاً من دار جار له يقال له قتادة، وأودعها عند يهودي، فلما اتُّهم خاف هو وإخوته المعرّة، فرموا بها اليهودي، وأتوا رسول الله ﷺ وحلفوا على براءة أخيهم، فصدّقهم وهمّ بقطع يد اليهودي، فنزلت الآيات ببراءة اليهودي وإدانة طعمة، فلما افتُضح، وكان منافقاً، أعلن ردّته وهرب إلى مكة، فنقب جدار منزل ليسرق فسقط عليه الجدار فمات كافراً. «إنا أنزلنا إليك الكتاب بالحق لتحكم بين الناس بما أراك الله»، لا بمجرد رأي رآه غيرك، وعاتبه ربه: ولا تكن للخائنين مدافعاً عنهم، واستغفر الله مما هممت به من عقوبة اليهودي، إن الله كان غفوراً رحيماً، ولا تجادل عن الذين يختانون أنفسهم، إن الله لا يحب من كان خوّاناً أثيماً. يستخفون من الناس حياءً منهم، ولا يستخفون من الله، وهو معهم إذ يبيّتون ما لا يرضى من القول، وكان الله بما يعملون محيطاً. ثم عاتب الذين وقفوا إلى جنب بني أُبَيرق: ها أنتم جادلتم عنهم في الحياة الدنيا، فمن يجادل الله عنهم يوم القيامة، أم من يكون عليهم وكيلاً؟", "h": ["لا يجوز الحكم بغير ما أنزل الله تعالى في كتابه وعلى لسان رسوله ﷺ.", "لا يجوز الوقوف إلى جنب الخونة الظالمين نصرةً لهم.", "وجوب الاستغفار من الذنب كبيراً كان أو صغيراً.", "وجوب بغض الخوّان الأثيم أيّاً كان.", "استحباب الوعظ والتذكير بأحوال يوم القيامة."], "k": "«يستخفون من الناس ولا يستخفون من الله»… ما الذي أستحي أن يراه الناس، ولا أستحي أن يراه ربي؟"}, {"lbl": "الآيات ١١٠ – ١١٣", "q": "وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورٗا رَّحِيمٗا ﴿١١٠﴾ وَمَن يَكۡسِبۡ إِثۡمٗا فَإِنَّمَا يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿١١١﴾ وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمٗا ثُمَّ يَرۡمِ بِهِۦ بَرِيٓـٔٗا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ﴿١١٢﴾ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ مِّنۡهُمۡ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ مِن شَيۡءٖۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمٗا ﴿١١٣﴾", "w": [["سوءاً", "ما يسيء إلى النفس أو إلى الغير."], ["أو يظلم نفسه", "بغشيان الذنوب وارتكاب الخطايا."], ["إثماً", "ما كان ضاراً بالنفس مفسداً لها."], ["بريئاً", "من لم يجنِ جناية قد اتُّهم بها."], ["احتمل بهتاناً", "تحمّل بهتاناً، وهو الكذب المحيّر لمن رُمي به."], ["الكتاب والحكمة", "الكتاب: القرآن، والحكمة: السنة."]], "m": "هذا السياق معطوف على حادثة ابن أُبَيرق، يحمل الرحمة الإلهية للذين تورّطوا في الوقوف إلى جنب الخائن: فمن يعمل سوءاً يؤذي به غيره، أو يظلم نفسه بذنب، ثم يستغفر الله ويُنيب إليه، يجد الله غفوراً رحيماً. ومن يكسب ذنباً فإنما يكسبه على نفسه، إذ هي التي تتدنّس به وتؤاخذ بمقتضاه، ولا يؤاخذ به غيرها، وكان الله عليماً حكيماً. ومن يرتكب خطيئة أو إثماً ثم يرمي به بريئاً منه فقد تحمّل بهتاناً وإثماً مبيناً قد يُصليه نار جهنم. ثم امتنّ على رسوله ﷺ: لولا فضل الله عليك ورحمته لهمّت طائفة منهم، وهم بنو أُبَيرق، أن يضلّوك عن الحكم بالحق، وما يضلّون إلا أنفسهم، وما يضرّونك من شيء، وأنزل الله عليك القرآن والحكمة، وعلّمك ما لم تكن تعلم، وكان فضل الله عليك عظيماً.", "h": ["تقرير مبدأ أن التوبة تجُبّ ما قبلها، ومن تاب تاب الله عليه.", "عظم ذنب من يكذب على البرآء ويتّهم الأمناء بالخيانة.", "تأثير الكلام على النفوس، حتى إن الرسول ﷺ كاد يضلّله بنو أُبَيرق فيبرّئ الخائن ويدين البريء، إلا أن الله عصمه.", "عاقبة الظلم عائدة على الظالم."], "k": "هل اتهمتُ أحداً بما ليس فيه، ولو بظنٍّ أو كلمة؟ وهل أستغفر وأصلح ما أفسدت؟"}]$j$::jsonb then 0 else 1 end;
