insert into public.tdb_cards(topic, i, body) select 75, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٩٥ – ٩٦", "q": "لَّا يَسۡتَوِي ٱلۡقَٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِينَ غَيۡرُ أُوْلِي ٱلضَّرَرِ وَٱلۡمُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَٰعِدِينَ دَرَجَةٗۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمٗا ﴿٩٥﴾ دَرَجَٰتٖ مِّنۡهُ وَمَغۡفِرَةٗ وَرَحۡمَةٗۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا ﴿٩٦﴾", "w": [["أولو الضرر", "العميان والعرج والمرضى."], ["درجة", "منزلة عالية في الجنة."], ["الحسنى", "الجنة."]], "m": "رُوي أن ابن أم مكتوم رضي الله عنه لما نزلت الآية بصيغة: «لا يستوي القاعدون من المؤمنين والمجاهدون في سبيل الله بأموالهم وأنفسهم» أتى النبي ﷺ فقال: كيف وأنا أعمى يا رسول الله؟ فما برح حتى نزلت «غير أولي الضرر» فأُدخلت في الآية. فنفى الله أن يستوي في الأجر والمنزلة من يجاهد بماله ونفسه ومن لا يجاهد بخلاً بماله وضنّاً بنفسه، واستثنى أولي الأعذار من مرض ونحوه، فلهم أجر المجاهدين لحسن نياتهم وعدم استطاعتهم، وكلاً وعد الله الحسنى، وهي الجنة. وفضّل الله المجاهدين على القاعدين لعذر درجة، وفضّلهم على القاعدين لغير عذر أجراً عظيماً، درجات منه ومغفرة ورحمة، وكان الله غفوراً رحيماً، اللهم اغفر لنا وارحمنا معهم.", "h": ["بيان فضل المجاهدين على غيرهم من المؤمنين الذين لا يجاهدون.", "أصحاب الأعذار الشرعية ينالون أجر المجاهدين إن كانت لهم رغبة في الجهاد ولم يقدروا عليه لما قام بهم من أعذار، وللمجاهدين فعلاً درجة تخصّهم دون ذوي الأعذار."], "k": "هل لي نية صادقة في خير عجزت عنه؟ فالنية الصادقة تبلغ ما لا يبلغه العمل."}, {"lbl": "الآيات ٩٧ – ١٠٠", "q": "إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡ قَالُواْ فِيمَ كُنتُمۡۖ قَالُواْ كُنَّا مُسۡتَضۡعَفِينَ فِي ٱلۡأَرۡضِۚ قَالُوٓاْ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَٰسِعَةٗ فَتُهَاجِرُواْ فِيهَاۚ فَأُوْلَـٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا ﴿٩٧﴾ إِلَّا ٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ لَا يَسۡتَطِيعُونَ حِيلَةٗ وَلَا يَهۡتَدُونَ سَبِيلٗا ﴿٩٨﴾ فَأُوْلَـٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا ﴿٩٩﴾ ۞وَمَن يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمٗا كَثِيرٗا وَسَعَةٗۚ وَمَن يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿١٠٠﴾", "w": [["توفّاهم", "تقبض أرواحهم عند نهاية آجالهم."], ["ظالمي أنفسهم", "بتركهم الهجرة وقد وجبت عليهم."], ["فيمَ كنتم", "في أي شيء كنتم من دينكم؟"], ["مصيراً", "مأوى ومسكناً."], ["حيلة", "قدرة على التحوّل."], ["مراغماً", "مكاناً وداراً لهجرته يُرغم ويُذلّ به من كان يؤذيه في داره."], ["وسعة", "في رزقه."], ["وقع أجره على الله", "وجب أجره في هجرته على الله تعالى."]], "m": "لما كانت الهجرة من آثار الجهاد، ذكر الله القاعدين عنها: إن الذين تتوفّاهم الملائكة ظالمي أنفسهم، حيث تركوا الهجرة ومكثوا في دار الهوان يضطهدهم العدو ويحول بينهم وبين عبادة ربهم، تقول لهم الملائكة عند قبض أرواحهم: فيمَ كنتم؟ فيقولون معتذرين: كنا مستضعفين في الأرض، فتردّ عليهم: ألم تكن أرض الله واسعة فتهاجروا فيها وتعبدوا ربكم؟ فأولئك مأواهم جهنم وساءت مصيراً. ثم استثنى أصحاب الأعذار: المستضعفين من الرجال بالعلل، والنساء والولدان بالضعف الملازم لهم، لا يستطيعون حيلة ولا يهتدون سبيلاً إلى دار الهجرة، فأولئك عسى الله أن يعفو عنهم، وكان الله عفوّاً غفوراً. ثم أخبر أن من يهاجر في سبيل الله، لا في سبيل دنيا يصيبها أو امرأة يتزوّجها، يجد في الأرض مذهباً يذهب إليه وداراً ينزل بها ورزقاً واسعاً يُرغم به عدوه، ومن خرج من بيته مهاجراً إلى الله ورسوله ثم أدركه الموت في الطريق فقد وجب أجره على الله كاملاً، وكان الله غفوراً رحيماً.", "h": ["وجوب الهجرة عندما يُحال بين المؤمن وعبادة ربه تعالى، إذ لم يُخلق إلا لها.", "ترك الهجرة كبيرة من كبائر الذنوب، يستوجب صاحبها دخول النار.", "أصحاب الأعذار كما سقط عنهم واجب الجهاد يسقط عنهم واجب الهجرة.", "فضل الهجرة في سبيل الله تعالى.", "من مات في طريق هجرته أُعطي أجر المهاجر كاملاً غير منقوص، وهو الجنة."], "k": "«ومن يخرج من بيته مهاجراً إلى الله ورسوله»… ما العادة أو المكان الذي أحتاج أن «أهاجر» منه إلى الله؟"}, {"lbl": "الآيات ١٠١ – ١٠٤", "q": "وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا ﴿١٠١﴾ وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا ﴿١٠٢﴾ فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا ﴿١٠٣﴾ وَلَا تَهِنُواْ فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا ﴿١٠٤﴾", "w": [["ضربتم في الأرض", "سافرتم مسافة قصر، وهي أربعة بُرُد، أي ثمانية وأربعون ميلاً."], ["أن تقصروا من الصلاة", "بأن تصلّوا الظهر والعصر والعشاء ركعتين ركعتين."], ["إن خفتم أن يفتنكم", "خرج مخرج الغالب، فليس الخوف بشرط في القصر، وإنما الشرط السفر."], ["حذرهم", "الحيطة والأهبة لما عسى أن يحدث من العدو."], ["وأسلحتهم", "جمع سلاح، وهو ما يُقاتل به."], ["لا جناح عليكم", "لا حرج عليكم في وضع الأسلحة."], ["قضيتم الصلاة", "أدّيتموها وفرغتم منها."], ["فإذا اطمأننتم", "ذهب الخوف فحصلت الطمأنينة بالأمن."], ["كتاباً موقوتاً", "فرضاً ذا وقت معيّن تؤدّى فيه، لا تتقدّمه ولا تتأخر عنه."], ["ولا تهنوا", "لا تضعفوا."], ["تألمون", "تتألمون."]], "m": "بمناسبة الهجرة، والسفر من لوازمها، ذكر الله رخصة قصر الصلاة الرباعية إلى ركعتين في السفر، وبيّنت السنة أن المسافر يقصر ولو أمن، فقيد الخوف غالبيّ فقط. ثم بيّن صلاة الخوف: أن ينقسم الجيش قسمين، قسم يقف تجاه العدو وقسم يصلي مع القائد ركعة ثم يتمّون لأنفسهم ويقفون تجاه العدو، ويأتي القسم الآخر فيصلي بهم الإمام ركعة ويتمّون لأنفسهم، وهم في الحالين آخذون أسلحتهم، إذ ودّ الذين كفروا لو تغفلون عن أسلحتكم وأمتعتكم فيميلون عليكم ميلة واحدة، ورخّص لهم في وضعها إن كان بهم أذى من مطر أو مرض، مع أخذ الحذر. ثم أمرهم إذا قضوا الصلاة أن يذكروا الله قياماً وقعوداً وعلى جنوبهم، لاسيما عند لقاء العدو لما فيه من القوة الروحية، فإذا اطمأنّوا أقاموا الصلاة تامة بحدودها وأركانها، إن الصلاة كانت على المؤمنين فرضاً موقوتاً. ثم قال: ولا تضعفوا في طلب العدو، إن تكونوا تألمون لجراحاتكم فإنهم يألمون كما تألمون، وترجون من الله من النصر والمثوبة ما لا يرجون، فأنتم أحق بالصبر والجلد، وكان الله عليماً حكيماً.", "h": ["مشروعية صلاة القصر، وهي رخصة أكّدها رسول الله ﷺ بقوله وعمله فأصبحت سنة مؤكدة لا ينبغي تركها.", "مشروعية صلاة الخوف وبيان كيفيتها.", "تأكّد صلاة الجماعة، بحيث لا تُترك حتى في ساعة الخوف والقتال.", "استحباب ذكر الله تعالى بعد الصلاة وعلى كل حال، من قيام وقعود واضطجاع.", "تقرير فرضية الصلاة، ووجوب أدائها في أوقاتها الموقوتة لها.", "حرمة الوهن والضعف إزاء حرب العدو، والاستعانة على قتاله بذكر الله ورجائه."], "k": "لم تسقط الصلاة حتى في ساعة القتال… فما عذري حين أؤخّرها عن وقتها؟"}, {"lbl": "الآيات ١٠٥ – ١٠٩", "q": "إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَيۡنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا ﴿١٠٥﴾ وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ﴿١٠٦﴾ وَلَا تُجَٰدِلۡ عَنِ ٱلَّذِينَ يَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمٗا ﴿١٠٧﴾ يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا ﴿١٠٨﴾ هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ جَٰدَلۡتُمۡ عَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلٗا ﴿١٠٩﴾", "w": [["بما أراك الله", "بما علّمكه بواسطة الوحي."], ["خصيماً", "مخاصماً بالغاً في الخصومة مبلغاً عظيماً."], ["تجادل", "تخاصم."], ["يختانون أنفسهم", "يحاولون خيانة أنفسهم."], ["يستخفون", "يطلبون إخفاء أنفسهم عن الناس."], ["وهو معهم", "بعلمه تعالى وقدرته."], ["يبيّتون", "يدبّرون الأمر في خفاء ومكر وخديعة."], ["وكيلاً", "الوكيل: من ينوب عن آخر في تحقيق غرض من الأغراض."]], "m": "رُوي أن هذه الآيات نزلت في طعمة بن أُبَيرق وإخوته، وكان قد سرق درعاً من دار جار له يقال له قتادة، وأودعها عند يهودي، فلما اتُّهم خاف هو وإخوته المعرّة، فرموا بها اليهودي، وأتوا رسول الله ﷺ وحلفوا على براءة أخيهم، فصدّقهم وهمّ بقطع يد اليهودي، فنزلت الآيات ببراءة اليهودي وإدانة طعمة، فلما افتُضح، وكان منافقاً، أعلن ردّته وهرب إلى مكة، فنقب جدار منزل ليسرق فسقط عليه الجدار فمات كافراً. «إنا أنزلنا إليك الكتاب بالحق لتحكم بين الناس بما أراك الله»، لا بمجرد رأي رآه غيرك، وعاتبه ربه: ولا تكن للخائنين مدافعاً عنهم، واستغفر الله مما هممت به من عقوبة اليهودي، إن الله كان غفوراً رحيماً، ولا تجادل عن الذين يختانون أنفسهم، إن الله لا يحب من كان خوّاناً أثيماً. يستخفون من الناس حياءً منهم، ولا يستخفون من الله، وهو معهم إذ يبيّتون ما لا يرضى من القول، وكان الله بما يعملون محيطاً. ثم عاتب الذين وقفوا إلى جنب بني أُبَيرق: ها أنتم جادلتم عنهم في الحياة الدنيا، فمن يجادل الله عنهم يوم القيامة، أم من يكون عليهم وكيلاً؟", "h": ["لا يجوز الحكم بغير ما أنزل الله تعالى في كتابه وعلى لسان رسوله ﷺ.", "لا يجوز الوقوف إلى جنب الخونة الظالمين نصرةً لهم.", "وجوب الاستغفار من الذنب كبيراً كان أو صغيراً.", "وجوب بغض الخوّان الأثيم أيّاً كان.", "استحباب الوعظ والتذكير بأحوال يوم القيامة."], "k": "«يستخفون من الناس ولا يستخفون من الله»… ما الذي أستحي أن يراه الناس، ولا أستحي أن يراه ربي؟"}, {"lbl": "الآيات ١١٠ – ١١٣", "q": "وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورٗا رَّحِيمٗا ﴿١١٠﴾ وَمَن يَكۡسِبۡ إِثۡمٗا فَإِنَّمَا يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿١١١﴾ وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمٗا ثُمَّ يَرۡمِ بِهِۦ بَرِيٓـٔٗا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ﴿١١٢﴾ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ مِّنۡهُمۡ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ مِن شَيۡءٖۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمٗا ﴿١١٣﴾", "w": [["سوءاً", "ما يسيء إلى النفس أو إلى الغير."], ["أو يظلم نفسه", "بغشيان الذنوب وارتكاب الخطايا."], ["إثماً", "ما كان ضاراً بالنفس مفسداً لها."], ["بريئاً", "من لم يجنِ جناية قد اتُّهم بها."], ["احتمل بهتاناً", "تحمّل بهتاناً، وهو الكذب المحيّر لمن رُمي به."], ["الكتاب والحكمة", "الكتاب: القرآن، والحكمة: السنة."]], "m": "هذا السياق معطوف على حادثة ابن أُبَيرق، يحمل الرحمة الإلهية للذين تورّطوا في الوقوف إلى جنب الخائن: فمن يعمل سوءاً يؤذي به غيره، أو يظلم نفسه بذنب، ثم يستغفر الله ويُنيب إليه، يجد الله غفوراً رحيماً. ومن يكسب ذنباً فإنما يكسبه على نفسه، إذ هي التي تتدنّس به وتؤاخذ بمقتضاه، ولا يؤاخذ به غيرها، وكان الله عليماً حكيماً. ومن يرتكب خطيئة أو إثماً ثم يرمي به بريئاً منه فقد تحمّل بهتاناً وإثماً مبيناً قد يُصليه نار جهنم. ثم امتنّ على رسوله ﷺ: لولا فضل الله عليك ورحمته لهمّت طائفة منهم، وهم بنو أُبَيرق، أن يضلّوك عن الحكم بالحق، وما يضلّون إلا أنفسهم، وما يضرّونك من شيء، وأنزل الله عليك القرآن والحكمة، وعلّمك ما لم تكن تعلم، وكان فضل الله عليك عظيماً.", "h": ["تقرير مبدأ أن التوبة تجُبّ ما قبلها، ومن تاب تاب الله عليه.", "عظم ذنب من يكذب على البرآء ويتّهم الأمناء بالخيانة.", "تأثير الكلام على النفوس، حتى إن الرسول ﷺ كاد يضلّله بنو أُبَيرق فيبرّئ الخائن ويدين البريء، إلا أن الله عصمه.", "عاقبة الظلم عائدة على الظالم."], "k": "هل اتهمتُ أحداً بما ليس فيه، ولو بظنٍّ أو كلمة؟ وهل أستغفر وأصلح ما أفسدت؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (76, 4, 114, 130, 'سورة النساء ١١٤ – ١٣٠', 'لا خير في كثير من نجواهم، ومكائد الشيطان، والصلح خير', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 76) = $j$[{"lbl": "الآيتان ١١٤ – ١١٥", "q": "۞لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا ﴿١١٤﴾ وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرًا ﴿١١٥﴾", "w": [["نجواهم", "النجوى: المسارّة بالكلام، ونجواهم: أحاديثهم التي يُسرّها بعضهم إلى بعض."], ["أو معروف", "ما عرفه الشرع فأباحه أو استحبّه أو أوجبه."], ["ابتغاء مرضات الله", "طلباً للحصول على رضا الله عز وجل."], ["نؤتيه", "نعطيه، والأجر العظيم: الجنة وما فيها من نعيم مقيم."], ["يشاقق الرسول", "يحادّه ويعاديه، كمن يقف في شقٍّ والآخر في شق."], ["ويتبع غير سبيل المؤمنين", "يخرج عن إجماع المسلمين."], ["نولّه ما تولّى", "نخذله فنتركه وما تولّاه من الباطل والضلال."], ["ونصله جهنم", "ندخله النار ونحرقه فيها."]], "m": "ما زال السياق في بني أُبَيرق، فأخبر الله أنه لا خير في كثير من أولئك المتناجين ولا في نجواهم، لنفاقهم وسوء طواياهم، إلا نجوى من أمر بصدقة تُعطى لمحتاج، أو معروف استحبّه الشارع أو أوجبه من البر والإحسان، أو إصلاح بين الناس للإبقاء على الألفة والمودة بين المسلمين، ومن يفعل ذلك طلباً لمرضاة الله فسوف يؤتيه أجراً عظيماً، هو الجنة. ثم توعّد أمثال طعمة: ومن يخالف الرسول ويعاديه من بعد ما عرف أنه رسول الله حقاً، ويخرج من جماعة المسلمين ويتبع غير سبيلهم، نتركه لكفره وضلاله خذلاناً له في الدنيا، ثم نُصليه جهنم، وساءت مصيراً.", "h": ["حرمة تناجي اثنين دون الثالث، لثبوت ذلك في السنة.", "الاجتماعات السرية لا خير فيها، إلا اجتماعاً كان لجمع صدقة، أو لأمر بمعروف، أو إصلاح بين متنازعين من المسلمين.", "حرمة الخروج عن أهل السنة والجماعة، واتباع الفرق الضالة التي لا تمثل الإسلام."], "k": "ما أكثر أحاديثي الخاصة اليوم؟ هل فيها صدقة أو معروف أو إصلاح بين الناس؟"}, {"lbl": "الآيات ١١٦ – ١٢١", "q": "إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا ﴿١١٦﴾ إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا وَإِن يَدۡعُونَ إِلَّا شَيۡطَٰنٗا مَّرِيدٗا ﴿١١٧﴾ لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِيبٗا مَّفۡرُوضٗا ﴿١١٨﴾ وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ وَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ فَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانٗا مُّبِينٗا ﴿١١٩﴾ يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا ﴿١٢٠﴾ أُوْلَـٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصٗا ﴿١٢١﴾", "w": [["أن يُشرك به", "أن يُعبد معه غيره من مخلوقاته بأي عبادة كانت."], ["إن يدعون", "ما يدعون."], ["إناثاً", "جمع أنثى، لأن الآلهة مؤنثة، أو أمواتاً لأن الميت يُطلق عليه لفظ أنثى بجامع عدم النفع."], ["مريداً", "مارداً على الشر والإغواء للفساد."], ["نصيباً مفروضاً", "حظاً معيّناً، أو حصة معلومة."], ["فليبتّكنّ", "البتك: القطع."], ["خلق الله", "ما خلقه الله تعالى."], ["يمنّيهم", "يجعلهم يتمنّون كذا وكذا ليلهيهم عن العمل الصالح."], ["محيصاً", "معدلاً أو مهرباً."]], "m": "«إن الله لا يغفر أن يُشرك به ويغفر ما دون ذلك لمن يشاء»: إخبار عن طعمة بأنه لا يُغفر له لموته على الشرك، أما إخوته الذين لم يموتوا مشركين فأمرهم إلى الله. ومن يشرك بالله فقد ضلّ عن طريق النجاة ضلالاً بعيداً. ثم بيّن قبح الشرك: إن المشركين ما يعبدون إلا أمواتاً لا يسمعون ولا يبصرون، وأسماؤها مؤنثة كاللات والعزى ومناة، وهم في الحقيقة يعبدون شيطاناً مريداً دعاهم إلى عبادة الأصنام، لعنه الله وأبلسه عند إبائه السجود لآدم، وقال: لأتخذنّ من عبادك نصيباً معلوماً يطيعونني، ولأضلّنّهم عن الهدى، ولأمنّينّهم الأماني الكاذبة بأنهم لا يلقون عذاباً، ولآمرنّهم فليبتّكنّ آذان الأنعام علامةً أنها للآلهة، ولآمرنّهم فليغيّرنّ خلق الله بالبدع والشرك والمعاصي كالوشم والخصاء. ومن يتخذ الشيطان ولياً من دون الله فقد خسر خسراناً مبيناً، إذ من والى الشيطان عادى الرحمن، يعدهم ويمنّيهم، وما يعدهم إلا غروراً، أولئك مأواهم جهنم ولا يجدون عنها محيصاً.", "h": ["سائر الذنوب، كبائرها وصغائرها، قد يغفرها الله تعالى لمن شاء، إلا الشرك فلا يغفره لمن مات عليه.", "عبدة الأصنام والأوهام والشهوات والأهواء هم في الباطن عبدة الشيطان، إذ هو الذي أمرهم فأطاعوه.", "من مظاهر طاعة الشيطان المعاصي كبيرها وصغيرها، إذ هو الذي أمر بها وأُطيع فيها.", "حرمة الوشم والوسم والخصاء إلا ما أذن فيه الشارع.", "سلاح الشيطان: العِدة الكاذبة، والأمنية الباطلة، والزينة الخادعة."], "k": "«يعدهم ويمنّيهم»… ما الأمنية التي يخدّرني بها الشيطان عن العمل الآن: «بعدين»، «لسه بدري»؟"}, {"lbl": "الآية ١٢٢", "q": "وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلٗا ﴿١٢٢﴾", "w": [["آمنوا", "صدّقوا بالله ورسوله."], ["وعملوا الصالحات", "الطاعات، إذ كل طاعة لله ورسوله عمل صالح."], ["قيلاً", "قولاً."]], "m": "لما بيّن الله جزاء الشرك والمشركين عبدة الشيطان، بيّن جزاء التوحيد والموحّدين عبيد الرحمن: أنه سيدخلهم بعد موتهم جنات تجري من تحت قصورها وأشجارها الأنهار، خالدين فيها أبداً بإذن ربهم، وعدهم ربهم بهذا وعد الصدق، وليس هناك أصدق وعداً ولا قولاً من الله تعالى.", "h": ["الإيمان الصادق والعمل الصالح الصحيح هما مفتاح الجنة وسبب دخولها.", "صدق وعد الله تعالى، وصدق قوله عز وجل.", "وجوب صدق الوعد من العبد؛ لأن خلف الوعد من النفاق.", "وجوب صدق القول والحديث؛ لأن الكذب من النفاق."], "k": "«ومن أصدق من الله قيلاً»… هل أنا صادق في وعودي للناس، كما أرجو أن يصدق الله وعده لي؟"}, {"lbl": "الآيات ١٢٣ – ١٢٦", "q": "لَّيۡسَ بِأَمَانِيِّكُمۡ وَلَآ أَمَانِيِّ أَهۡلِ ٱلۡكِتَٰبِۗ مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ وَلَا يَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا ﴿١٢٣﴾ وَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ نَقِيرٗا ﴿١٢٤﴾ وَمَنۡ أَحۡسَنُ دِينٗا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا ﴿١٢٥﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ مُّحِيطٗا ﴿١٢٦﴾", "w": [["أمانيّكم", "الأمنية: ما يقدّره المرء في نفسه ويشتهيه مما يتعذّر غالباً تحقيقه."], ["ملة إبراهيم", "عبادة الله وحده لا شريك له بما شرعه الله تعالى."], ["خليلاً", "الخليل: المحب الذي تخلّل حبُّه مسالك النفس، فهو أكبر من الحبيب."], ["محيطاً", "علماً وقدرة، إذ الكون كله تحت قهره."]], "m": "رُوي أن مسلماً ويهودياً تفاخرا، فزعم اليهودي أن نبيهم وكتابهم ودينهم قبل نبي المسلمين وكتابهم فهم أفضل، فحكم الله بينهما: ليس الأمر بأمانيّكم أيها المسلمون، ولا أمانيّ أهل الكتاب، وإنما هو سنة الله في تأثير الكسب على النفس بالتزكية أو التدسية؛ فمن يعمل سوءاً من الشرك والمعاصي يُجزَ به، ولا يجد له من دون الله ولياً ولا نصيراً، ومن يعمل من الصالحات من ذكر أو أنثى وهو مؤمن فأولئك يدخلون الجنة ولا يُظلمون نقيراً. ثم فضّل الإسلام: ومن أحسن ديناً ممن أسلم وجهه لله، فكل جوارحه تابعة له في طاعة الله، وهو محسن يتقن العبادة على نحو ما شرعها الله، واتبع ملة إبراهيم حنيفاً، واتخذ الله إبراهيم خليلاً. ولله ما في السموات وما في الأرض، رفعاً لما قد يُتوهّم من أن الخلّة تعني افتقار الله إلى إبراهيم، وكان الله بكل شيء محيطاً.", "h": ["ما عند الله لا يُنال بالتمنّي، ولكن بالإيمان والعمل الصالح، أو التقوى والصبر.", "الجزاء أثر طبيعي للعمل، وهو معنى «من يعمل سوءاً يُجزَ به».", "فضل الإسلام على سائر الأديان.", "شرف إبراهيم ﵇ باتخاذ ربه له خليلاً.", "غنى الله تعالى عن سائر مخلوقاته، وافتقار سائر مخلوقاته إليه عز وجل."], "k": "«ليس بأمانيّكم»… هل أعتمد على أنني مسلم فقط، أم أُتبِع ذلك بإسلام الوجه والإحسان؟"}, {"lbl": "الآيات ١٢٧ – ١٣٠", "q": "وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ ٱلَّـٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمٗا ﴿١٢٧﴾ وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضٗا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿١٢٨﴾ وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ﴿١٢٩﴾ وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمٗا ﴿١٣٠﴾", "w": [["يستفتونك", "يطلبون منك الفتيا في شأن النساء وميراثهن."], ["وما يُتلى عليكم", "يُقرأ عليكم في القرآن."], ["ما كُتب لهن", "ما فُرض لهن من المهور والميراث."], ["بالقسط", "بالعدل."], ["نشوزاً", "ترفّعاً وعدم طاعة."], ["وأُحضرت الأنفس الشحّ", "جُبلت النفوس على الشح فلا يفارقها."], ["فتذروها كالمعلّقة", "تتركوها كالمعلّقة، لا هي بالمتزوجة ولا المطلّقة."], ["من سعته", "من رزقه الواسع."], ["واسعاً حكيماً", "واسع الفضل، يعطي فضله حسب علمه وحكمته."]], "m": "كل آية من هذه الأربع تحمل حكماً: فالأولى نزلت جواباً لتساؤلات بعض الصحابة عن حقوق النساء بعد أن قرّرت أول السورة حق المرأة والطفل في الإرث، فقال: قل الله يفتيكم فيهن، وما يُتلى عليكم في أول السورة كافٍ: من كانت تحته يتيمة لا يرغب في نكاحها فليعطها مالها وليزوّجها غيره، ولا يحبسها لأجل مالها، وإن أراد نكاحها فليعطها مهر مثلها، وفي المستضعفين من الولدان أعطاهم حقهم في آية المواريث، وأن تقوموا لليتامى بالقسط، وما تفعلوا من خير فإن الله به عليم. والثانية: إن خافت امرأة من زوجها ترفّعاً أو إعراضاً، لكبر سنها مثلاً، فلا جناح عليهما أن يصطلحا، فتتنازل عن بعض حقها ليبقيها في بيتها عزيزة، والصلح خير من الفراق، وأُحضرت الأنفس الشح، فليراعِ الزوج ذلك، وإن تحسنوا وتتقوا فإن الله بما تعملون خبير. والثالثة: لن تستطيعوا العدل بين النساء في الحب والجماع ولو حرصتم، أما القسمة والنفقة والعشرة بالمعروف فمستطاعة، فلا تميلوا كل الميل إلى إحداهن فتذروا الأخرى كالمعلّقة، وإن تصلحوا وتتقوا فإن الله كان غفوراً رحيماً. والرابعة: إن تعذّر الصلح فتفرّقا بالمعروف يُغنِ الله كلاً منهما من سعته، فيرزق المرأة زوجاً خيراً، والرجل امرأة خيراً.", "h": ["تقرير مبدأ إرث النساء والأطفال، والمحافظة على مال اليتامى وحرمة أكلها.", "استحباب الصلح بين الزوجين عند تعذّر البقاء معاً إلا به.", "تعذّر العدل بين الزوجات في الحب والوطء استلزم عدم المؤاخذة به، واكتفى الشارع بالعدل في الفراش والطعام والشراب والكسوة والمعاشرة بالمعروف.", "الترغيب في الإصلاح والتقوى وفعل الخيرات.", "الفرقة بين الزوجين إن كانت على مبدأ الإصلاح والتقوى أعقبت خيراً عاجلاً أو آجلاً."], "k": "«والصلح خير»… هل بيني وبين أحد خلاف يحتاج أن أتنازل فيه عن بعض حقي لأجل الصلح؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 76;
insert into public.tdb_cards(topic, i, body) select 76, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١١٤ – ١١٥", "q": "۞لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا ﴿١١٤﴾ وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرًا ﴿١١٥﴾", "w": [["نجواهم", "النجوى: المسارّة بالكلام، ونجواهم: أحاديثهم التي يُسرّها بعضهم إلى بعض."], ["أو معروف", "ما عرفه الشرع فأباحه أو استحبّه أو أوجبه."], ["ابتغاء مرضات الله", "طلباً للحصول على رضا الله عز وجل."], ["نؤتيه", "نعطيه، والأجر العظيم: الجنة وما فيها من نعيم مقيم."], ["يشاقق الرسول", "يحادّه ويعاديه، كمن يقف في شقٍّ والآخر في شق."], ["ويتبع غير سبيل المؤمنين", "يخرج عن إجماع المسلمين."], ["نولّه ما تولّى", "نخذله فنتركه وما تولّاه من الباطل والضلال."], ["ونصله جهنم", "ندخله النار ونحرقه فيها."]], "m": "ما زال السياق في بني أُبَيرق، فأخبر الله أنه لا خير في كثير من أولئك المتناجين ولا في نجواهم، لنفاقهم وسوء طواياهم، إلا نجوى من أمر بصدقة تُعطى لمحتاج، أو معروف استحبّه الشارع أو أوجبه من البر والإحسان، أو إصلاح بين الناس للإبقاء على الألفة والمودة بين المسلمين، ومن يفعل ذلك طلباً لمرضاة الله فسوف يؤتيه أجراً عظيماً، هو الجنة. ثم توعّد أمثال طعمة: ومن يخالف الرسول ويعاديه من بعد ما عرف أنه رسول الله حقاً، ويخرج من جماعة المسلمين ويتبع غير سبيلهم، نتركه لكفره وضلاله خذلاناً له في الدنيا، ثم نُصليه جهنم، وساءت مصيراً.", "h": ["حرمة تناجي اثنين دون الثالث، لثبوت ذلك في السنة.", "الاجتماعات السرية لا خير فيها، إلا اجتماعاً كان لجمع صدقة، أو لأمر بمعروف، أو إصلاح بين متنازعين من المسلمين.", "حرمة الخروج عن أهل السنة والجماعة، واتباع الفرق الضالة التي لا تمثل الإسلام."], "k": "ما أكثر أحاديثي الخاصة اليوم؟ هل فيها صدقة أو معروف أو إصلاح بين الناس؟"}, {"lbl": "الآيات ١١٦ – ١٢١", "q": "إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا ﴿١١٦﴾ إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا وَإِن يَدۡعُونَ إِلَّا شَيۡطَٰنٗا مَّرِيدٗا ﴿١١٧﴾ لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِيبٗا مَّفۡرُوضٗا ﴿١١٨﴾ وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ وَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ فَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانٗا مُّبِينٗا ﴿١١٩﴾ يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا ﴿١٢٠﴾ أُوْلَـٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصٗا ﴿١٢١﴾", "w": [["أن يُشرك به", "أن يُعبد معه غيره من مخلوقاته بأي عبادة كانت."], ["إن يدعون", "ما يدعون."], ["إناثاً", "جمع أنثى، لأن الآلهة مؤنثة، أو أمواتاً لأن الميت يُطلق عليه لفظ أنثى بجامع عدم النفع."], ["مريداً", "مارداً على الشر والإغواء للفساد."], ["نصيباً مفروضاً", "حظاً معيّناً، أو حصة معلومة."], ["فليبتّكنّ", "البتك: القطع."], ["خلق الله", "ما خلقه الله تعالى."], ["يمنّيهم", "يجعلهم يتمنّون كذا وكذا ليلهيهم عن العمل الصالح."], ["محيصاً", "معدلاً أو مهرباً."]], "m": "«إن الله لا يغفر أن يُشرك به ويغفر ما دون ذلك لمن يشاء»: إخبار عن طعمة بأنه لا يُغفر له لموته على الشرك، أما إخوته الذين لم يموتوا مشركين فأمرهم إلى الله. ومن يشرك بالله فقد ضلّ عن طريق النجاة ضلالاً بعيداً. ثم بيّن قبح الشرك: إن المشركين ما يعبدون إلا أمواتاً لا يسمعون ولا يبصرون، وأسماؤها مؤنثة كاللات والعزى ومناة، وهم في الحقيقة يعبدون شيطاناً مريداً دعاهم إلى عبادة الأصنام، لعنه الله وأبلسه عند إبائه السجود لآدم، وقال: لأتخذنّ من عبادك نصيباً معلوماً يطيعونني، ولأضلّنّهم عن الهدى، ولأمنّينّهم الأماني الكاذبة بأنهم لا يلقون عذاباً، ولآمرنّهم فليبتّكنّ آذان الأنعام علامةً أنها للآلهة، ولآمرنّهم فليغيّرنّ خلق الله بالبدع والشرك والمعاصي كالوشم والخصاء. ومن يتخذ الشيطان ولياً من دون الله فقد خسر خسراناً مبيناً، إذ من والى الشيطان عادى الرحمن، يعدهم ويمنّيهم، وما يعدهم إلا غروراً، أولئك مأواهم جهنم ولا يجدون عنها محيصاً.", "h": ["سائر الذنوب، كبائرها وصغائرها، قد يغفرها الله تعالى لمن شاء، إلا الشرك فلا يغفره لمن مات عليه.", "عبدة الأصنام والأوهام والشهوات والأهواء هم في الباطن عبدة الشيطان، إذ هو الذي أمرهم فأطاعوه.", "من مظاهر طاعة الشيطان المعاصي كبيرها وصغيرها، إذ هو الذي أمر بها وأُطيع فيها.", "حرمة الوشم والوسم والخصاء إلا ما أذن فيه الشارع.", "سلاح الشيطان: العِدة الكاذبة، والأمنية الباطلة، والزينة الخادعة."], "k": "«يعدهم ويمنّيهم»… ما الأمنية التي يخدّرني بها الشيطان عن العمل الآن: «بعدين»، «لسه بدري»؟"}, {"lbl": "الآية ١٢٢", "q": "وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلٗا ﴿١٢٢﴾", "w": [["آمنوا", "صدّقوا بالله ورسوله."], ["وعملوا الصالحات", "الطاعات، إذ كل طاعة لله ورسوله عمل صالح."], ["قيلاً", "قولاً."]], "m": "لما بيّن الله جزاء الشرك والمشركين عبدة الشيطان، بيّن جزاء التوحيد والموحّدين عبيد الرحمن: أنه سيدخلهم بعد موتهم جنات تجري من تحت قصورها وأشجارها الأنهار، خالدين فيها أبداً بإذن ربهم، وعدهم ربهم بهذا وعد الصدق، وليس هناك أصدق وعداً ولا قولاً من الله تعالى.", "h": ["الإيمان الصادق والعمل الصالح الصحيح هما مفتاح الجنة وسبب دخولها.", "صدق وعد الله تعالى، وصدق قوله عز وجل.", "وجوب صدق الوعد من العبد؛ لأن خلف الوعد من النفاق.", "وجوب صدق القول والحديث؛ لأن الكذب من النفاق."], "k": "«ومن أصدق من الله قيلاً»… هل أنا صادق في وعودي للناس، كما أرجو أن يصدق الله وعده لي؟"}, {"lbl": "الآيات ١٢٣ – ١٢٦", "q": "لَّيۡسَ بِأَمَانِيِّكُمۡ وَلَآ أَمَانِيِّ أَهۡلِ ٱلۡكِتَٰبِۗ مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ وَلَا يَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا ﴿١٢٣﴾ وَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ نَقِيرٗا ﴿١٢٤﴾ وَمَنۡ أَحۡسَنُ دِينٗا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا ﴿١٢٥﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ مُّحِيطٗا ﴿١٢٦﴾", "w": [["أمانيّكم", "الأمنية: ما يقدّره المرء في نفسه ويشتهيه مما يتعذّر غالباً تحقيقه."], ["ملة إبراهيم", "عبادة الله وحده لا شريك له بما شرعه الله تعالى."], ["خليلاً", "الخليل: المحب الذي تخلّل حبُّه مسالك النفس، فهو أكبر من الحبيب."], ["محيطاً", "علماً وقدرة، إذ الكون كله تحت قهره."]], "m": "رُوي أن مسلماً ويهودياً تفاخرا، فزعم اليهودي أن نبيهم وكتابهم ودينهم قبل نبي المسلمين وكتابهم فهم أفضل، فحكم الله بينهما: ليس الأمر بأمانيّكم أيها المسلمون، ولا أمانيّ أهل الكتاب، وإنما هو سنة الله في تأثير الكسب على النفس بالتزكية أو التدسية؛ فمن يعمل سوءاً من الشرك والمعاصي يُجزَ به، ولا يجد له من دون الله ولياً ولا نصيراً، ومن يعمل من الصالحات من ذكر أو أنثى وهو مؤمن فأولئك يدخلون الجنة ولا يُظلمون نقيراً. ثم فضّل الإسلام: ومن أحسن ديناً ممن أسلم وجهه لله، فكل جوارحه تابعة له في طاعة الله، وهو محسن يتقن العبادة على نحو ما شرعها الله، واتبع ملة إبراهيم حنيفاً، واتخذ الله إبراهيم خليلاً. ولله ما في السموات وما في الأرض، رفعاً لما قد يُتوهّم من أن الخلّة تعني افتقار الله إلى إبراهيم، وكان الله بكل شيء محيطاً.", "h": ["ما عند الله لا يُنال بالتمنّي، ولكن بالإيمان والعمل الصالح، أو التقوى والصبر.", "الجزاء أثر طبيعي للعمل، وهو معنى «من يعمل سوءاً يُجزَ به».", "فضل الإسلام على سائر الأديان.", "شرف إبراهيم ﵇ باتخاذ ربه له خليلاً.", "غنى الله تعالى عن سائر مخلوقاته، وافتقار سائر مخلوقاته إليه عز وجل."], "k": "«ليس بأمانيّكم»… هل أعتمد على أنني مسلم فقط، أم أُتبِع ذلك بإسلام الوجه والإحسان؟"}, {"lbl": "الآيات ١٢٧ – ١٣٠", "q": "وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ ٱلَّـٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمٗا ﴿١٢٧﴾ وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضٗا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿١٢٨﴾ وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ﴿١٢٩﴾ وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمٗا ﴿١٣٠﴾", "w": [["يستفتونك", "يطلبون منك الفتيا في شأن النساء وميراثهن."], ["وما يُتلى عليكم", "يُقرأ عليكم في القرآن."], ["ما كُتب لهن", "ما فُرض لهن من المهور والميراث."], ["بالقسط", "بالعدل."], ["نشوزاً", "ترفّعاً وعدم طاعة."], ["وأُحضرت الأنفس الشحّ", "جُبلت النفوس على الشح فلا يفارقها."], ["فتذروها كالمعلّقة", "تتركوها كالمعلّقة، لا هي بالمتزوجة ولا المطلّقة."], ["من سعته", "من رزقه الواسع."], ["واسعاً حكيماً", "واسع الفضل، يعطي فضله حسب علمه وحكمته."]], "m": "كل آية من هذه الأربع تحمل حكماً: فالأولى نزلت جواباً لتساؤلات بعض الصحابة عن حقوق النساء بعد أن قرّرت أول السورة حق المرأة والطفل في الإرث، فقال: قل الله يفتيكم فيهن، وما يُتلى عليكم في أول السورة كافٍ: من كانت تحته يتيمة لا يرغب في نكاحها فليعطها مالها وليزوّجها غيره، ولا يحبسها لأجل مالها، وإن أراد نكاحها فليعطها مهر مثلها، وفي المستضعفين من الولدان أعطاهم حقهم في آية المواريث، وأن تقوموا لليتامى بالقسط، وما تفعلوا من خير فإن الله به عليم. والثانية: إن خافت امرأة من زوجها ترفّعاً أو إعراضاً، لكبر سنها مثلاً، فلا جناح عليهما أن يصطلحا، فتتنازل عن بعض حقها ليبقيها في بيتها عزيزة، والصلح خير من الفراق، وأُحضرت الأنفس الشح، فليراعِ الزوج ذلك، وإن تحسنوا وتتقوا فإن الله بما تعملون خبير. والثالثة: لن تستطيعوا العدل بين النساء في الحب والجماع ولو حرصتم، أما القسمة والنفقة والعشرة بالمعروف فمستطاعة، فلا تميلوا كل الميل إلى إحداهن فتذروا الأخرى كالمعلّقة، وإن تصلحوا وتتقوا فإن الله كان غفوراً رحيماً. والرابعة: إن تعذّر الصلح فتفرّقا بالمعروف يُغنِ الله كلاً منهما من سعته، فيرزق المرأة زوجاً خيراً، والرجل امرأة خيراً.", "h": ["تقرير مبدأ إرث النساء والأطفال، والمحافظة على مال اليتامى وحرمة أكلها.", "استحباب الصلح بين الزوجين عند تعذّر البقاء معاً إلا به.", "تعذّر العدل بين الزوجات في الحب والوطء استلزم عدم المؤاخذة به، واكتفى الشارع بالعدل في الفراش والطعام والشراب والكسوة والمعاشرة بالمعروف.", "الترغيب في الإصلاح والتقوى وفعل الخيرات.", "الفرقة بين الزوجين إن كانت على مبدأ الإصلاح والتقوى أعقبت خيراً عاجلاً أو آجلاً."], "k": "«والصلح خير»… هل بيني وبين أحد خلاف يحتاج أن أتنازل فيه عن بعض حقي لأجل الصلح؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (77, 4, 131, 147, 'سورة النساء ١٣١ – ١٤٧', 'كونوا قوّامين بالقسط، وصفات المنافقين، و«ما يفعل الله بعذابكم إن شكرتم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 77) = $j$[{"lbl": "الآيات ١٣١ – ١٣٤", "q": "وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا ﴿١٣١﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿١٣٢﴾ إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا ﴿١٣٣﴾ مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا ﴿١٣٤﴾", "w": [["وله ما في السموات وما في الأرض", "خلقاً وملكاً وتصرّفاً وتدبيراً."], ["وصّينا", "عهدنا إليهم بالتقوى."], ["أوتوا الكتاب", "اليهود والنصارى."], ["وكيلاً", "الوكيل: من يُفوَّض إليه الأمر كله ويقوم بتدبيره على أحسن الوجوه."], ["ثواب الدنيا", "جزاء العمل فيها."], ["ثواب الآخرة", "جزاء العمل فيها، وهو الجنة."], ["سميعاً بصيراً", "سميعاً لأقوال العباد، بصيراً بأعمالهم، وسيجزيهم بها."]], "m": "لما وعد الله الزوجين المتفرّقين بالإغناء، ذكر أنه يملك ما في السموات وما في الأرض، فهو قادر على إغنائهما. ثم خاطب الأمة جمعاء: ولقد وصّينا الذين أوتوا الكتاب من قبلكم وإياكم أن اتقوا الله، فلا تُقدموا على مخالفته ولا تخرجوا عن طاعته، وإن تكفروا فإن ذلك لا يضرّه شيئاً، فله ما في السموات وما في الأرض، وهو الغني الحميد، وكفى بالله وكيلاً. ثم أخبر أنه قادر على إذهاب الناس كلهم والإتيان بآخرين. ثم رغّب عباده فيما عنده: من كان يريد بعمله ثواب الدنيا فعند الله ثواب الدنيا والآخرة، فلِمَ يقصر العبد عمله على ثواب الدنيا وهو يعلم أن ثواب الآخرة عند الله أيضاً؟ فليطلب الثوابين معاً بالإيمان والتقوى والإحسان، وكان الله سميعاً بصيراً، فلا يُخاف معه ضياع الأعمال.", "h": ["الوصية بالتقوى، وذلك بترك الشرك والمعاصي بعد الإيمان وعمل الصالحات.", "غنى الله تعالى عن سائر خلقه.", "قدرة الله تعالى على إذهاب الناس كلهم والإتيان بغيرهم.", "وجوب الإخلاص في العمل لله تعالى، وحرمة طلب الدنيا بعمل الآخرة."], "k": "«فعند الله ثواب الدنيا والآخرة»… لماذا أطلب بعملي الأقلّ، والله يعطي الاثنين؟"}, {"lbl": "الآيات ١٣٥ – ١٣٧", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿١٣٥﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا ﴿١٣٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا ﴿١٣٧﴾", "w": [["قوّامين", "جمع قوّام، وهو كثير القيام بالعدل."], ["بالقسط", "بالعدل، وهو الاستقامة والتسوية بين الخصوم."], ["تلووا", "تُحرّفوا الشهادة بألسنتكم."], ["أو تُعرضوا", "تتركوا أداءها أو بعض كلماتها."]], "m": "ينادي الله المؤمنين: كونوا قوّامين بالعدل، شهداء لله، إذ بشهادتكم ينتقل الحق من شخص إلى آخر، وقد أقامكم الله شهداء له في الأرض تؤدّى بواسطتكم الحقوق إلى أهلها، فأقيموا الشهادة لله ولو على أنفسكم أو الوالدين والأقربين، غنياً كان المشهود عليه أو فقيراً، فلا يحملنّكم غنى الغني ولا فقر الفقير على تحريف الشهادة أو كتمانها، فالله أولى بهما، فلا تتّبعوا الهوى أن تعدلوا، وإن تلووا ألسنتكم بالشهادة تحريفاً، أو تُعرضوا عنها فتتركوها، فإن الله كان بما تعملون خبيراً. وهي أعظم آية في هذا الباب. ثم دعا المؤمنين إلى تقوية إيمانهم ليبلغوا اليقين، ودعا أهل الكتاب إلى الإيمان الصحيح: آمنوا بالله ورسوله محمد ﷺ، والقرآن الذي نزّل على رسوله، والكتاب الذي أنزل من قبل، ومن يكفر بالله وملائكته وكتبه ورسله واليوم الآخر فقد ضلّ ضلالاً بعيداً. ثم قرّر: إن الذين آمنوا ثم كفروا، ثم آمنوا ثم كفروا، ثم ازدادوا كفراً، لم يكن الله ليغفر لهم ولا ليهديهم سبيلاً.", "h": ["وجوب العدل في القضاء والشهادة.", "حرمة شهادة الزور، وحرمة التخلّي عن الشهادة لمن تعيّنت عليه.", "وجوب الاستمرار على الإيمان وتقويته حتى الموت عليه.", "بيان أركان الإيمان: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر."], "k": "«ولو على أنفسكم أو الوالدين والأقربين»… هل أقول الحق حين يكون ضدّي أو ضدّ من أحب؟"}, {"lbl": "الآيات ١٣٨ – ١٤١", "q": "بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا ﴿١٣٨﴾ ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا ﴿١٣٩﴾ وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا ﴿١٤٠﴾ ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا ﴿١٤١﴾", "w": [["بشّر المنافقين", "البشارة: الخبر الذي تتأثر به بشرة من يُلقى إليه، خيراً كان أو شراً."], ["أولياء", "يوالونهم محبةً ونصرةً لهم على المؤمنين."], ["العزّة", "الغلبة والمنعة."], ["يُستهزأ بها", "يذكرونها استخفافاً بها وإنكاراً لها."], ["يخوضوا", "يتكلموا في موضوع آخر."], ["مثلهم", "في الكفر والإثم."], ["يتربّصون بكم", "ينتظرون متى يحصل لكم انهزام فيعلنون كفرهم."], ["نصيب", "من النصر، وعبّر عنه بالنصيب القليل لأن انتصارهم على المؤمنين قليل."], ["نستحوذ عليكم", "نستولِ عليكم ونمنعكم من المؤمنين إن قاتلوكم."], ["سبيلاً", "طريقاً إلى إذلالهم واستعبادهم والتسلّط عليهم."]], "m": "أمر الله رسوله ﷺ أن يخبر المنافقين، بلفظ البشارة تهكّماً، بأن لهم عذاباً أليماً، ثم وصفهم بأخسّ صفاتهم: الذين يتخذون الكافرين أولياء من دون المؤمنين، يعطونهم محبتهم ونصرتهم، أيبتغون عندهم العزة؟ فإن العزة لله جميعاً، فمن أعزّه الله عزّ، ومن أذلّه ذلّ، وتُطلب العزة بالإيمان وصالح الأعمال. ثم ذكّر المؤمنين بما أنزل عليهم في سورة الأنعام بمكة من النهي عن مجالسة أهل الباطل إذا خاضوا في الطعن في آيات الله، فلما أصبح للمنافقين في المدينة مجالس يخوضون فيها في آيات الله استهزاءً قال: إذا سمعتم آيات الله يُكفر بها ويُستهزأ بها فلا تقعدوا معهم حتى يخوضوا في حديث غيره، إنكم إذاً مثلهم في الإثم والجزاء، إن الله جامع المنافقين والكافرين في جهنم جميعاً. ثم وصفهم: الذين يتربّصون بكم الدوائر، فإن كان لكم فتح من الله قالوا: ألم نكن معكم؟ فأشركونا في الغنيمة، وإن كان للكافرين نصيب قالوا: ألم نستولِ عليكم ونمنعكم من المؤمنين؟ فأعطونا، يمسكون العصا من الوسط. فالله يحكم بينهم يوم القيامة، ولن يجعل الله للكافرين على المؤمنين سبيلاً لاستئصالهم أو إذلالهم ما داموا مؤمنين صادقين.", "h": ["حرمة اتخاذ الكافرين أولياء من دون المؤمنين.", "الباعث على اتخاذ الكافرين أولياء هو الرغبة في العزة، وهذا باطل، فالعزة لله ولا تُطلب إلا منه بالإيمان واتباع منهجه.", "حرمة مجالسة أهل الباطل إذا كانوا يخوضون في آيات الله نقداً واستهزاءً وسخرية.", "الرضا بالكفر كفر، والرضا بالإثم إثم.", "تكفّل الله تعالى بعزة المؤمنين الصادقين ومنعتهم، فلا يسلّط عليهم أعداءه فيستأصلونهم أو يذلّونهم."], "k": "«فلا تقعدوا معهم حتى يخوضوا في حديث غيره»… هل أقوم من مجلس يُستهزأ فيه بالدين، ولو كان مجلساً على الإنترنت؟"}, {"lbl": "الآيتان ١٤٢ – ١٤٣", "q": "إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا ﴿١٤٢﴾ مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا ﴿١٤٣﴾", "w": [["يخادعون الله", "بإظهارهم ما يحب من الإيمان والطاعات، وإخفائهم الكفر."], ["وهو خادعهم", "بالستر عليهم وعدم فضيحتهم وعدم إنزال العقوبة بهم عاجلاً."], ["يراؤون", "يُظهرون الطاعات للمؤمنين كأنهم مؤمنون وما هم بمؤمنين."], ["مذبذبين", "يتردّدون بين المؤمنين والكافرين، فأي جانب عزّ كانوا معه."]], "m": "أخبر الله أن المنافقين يخادعونه بإظهار الإيمان به وبرسوله وهم غير مؤمنين، إذ الخداع أن تُري من تخادعه ما يحبه منك وتستر عنه ما يكرهه، والله عاملهم بالمثل: أراهم ما يحبون، وستر عنهم ما يكرهون، وهو العذاب المعدّ لهم عاجلاً أو آجلاً. وإذا قاموا إلى الصلاة قاموا كسالى متباطئين، لأنهم لا يؤمنون بالثواب الأخروي، يراؤون المؤمنين بالأعمال الصالحة حتى لا يتهموهم بالكفر، ولا يذكرون الله إلا قليلاً في الصلاة وخارجها، لعدم إيمانهم به وعدم حبهم له. وهم مذبذبون بين الكفر والإيمان، لا إلى المؤمنين يسكنون، ولا إلى الكافرين، فهم في تردّد وحسرة دائمة، وهذه حال من يضلّه الله، ومن يضلل الله فلن تجد له سبيلاً.", "h": ["بيان صفات المنافقين.", "قبح الرياء وذمّ المرائين.", "ذم ترك الذكر والتقليل منه، لأمر الله تعالى بالإكثار منه في قوله: «يا أيها الذين آمنوا اذكروا الله ذكراً كثيراً».", "ذم الحيرة والتردّد في الأمور كلها."], "k": "«وإذا قاموا إلى الصلاة قاموا كسالى»… كيف أقوم إلى صلاتي القادمة؟"}, {"lbl": "الآيات ١٤٤ – ١٤٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا ﴿١٤٤﴾ إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا ﴿١٤٥﴾ إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَـٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا ﴿١٤٦﴾ مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا ﴿١٤٧﴾", "w": [["سلطاناً مبيناً", "حجة واضحة لتعذيبكم."], ["الدرك الأسفل", "الدرك كالطابق، والدركة كالدرجة."], ["وأصلحوا", "ما كانوا قد أفسدوه من العقائد والأعمال."], ["واعتصموا بالله", "تمسّكوا بدينه وتوكّلوا عليه."], ["وأخلصوا دينهم لله", "تخلّوا عن النفاق والشرك."]], "m": "ما زال السياق في إرشاد المؤمنين إلى ما يعزّهم ويكمّلهم، فنهاهم عن اتخاذ الكافرين أولياء من دون المؤمنين، بموادّتهم ومناصرتهم والثقة بهم والركون إليهم، وهدّدهم: أتريدون أن تجعلوا لله عليكم حجة واضحة، فيتخلّى عنكم ويسلّط عليكم أعداءه؟ ثم حذّرهم من النفاق أن يتسرّب إلى قلوبهم: إن المنافقين في الدرك الأسفل من النار، ولن تجد لهم نصيراً. ثم فتح باب التوبة رحمةً بعباده: إلا الذين تابوا فآمنوا حق الإيمان، وأصلحوا أعمالهم، واعتصموا بالله ونفضوا أيديهم من الكافرين، وأخلصوا دينهم لله فلم يراؤوا أحداً، فأولئك مع المؤمنين، وسوف يؤتي الله المؤمنين أجراً عظيماً. ثم قرّر غناه عن تعذيب خلقه: ما يفعل الله بعذابكم إن شكرتم وآمنتم؟ فالعبد مهما جنى وأساء إذا تاب وأصلح فآمن وشكر لا يعذّبه، وكان الله شاكراً لا يضيع المعروف عنده، عليماً.", "h": ["حرمة اتخاذ الكافرين أولياء من دون المؤمنين.", "إذا عصى المؤمنون ربهم فاتخذوا الكافرين أولياء سلّط الله عليهم أعداءهم فساموهم الخسف.", "التوبة تجُبّ ما قبلها، حتى إن التائب من ذنبه كمن لا ذنب له، مهما كان الذنب الذي غشيه.", "لا يعذّب الله تعالى المؤمن الشاكر لا في الدنيا ولا في الآخرة، فالإيمان والشكر أمان الإنسان."], "k": "«ما يفعل الله بعذابكم إن شكرتم وآمنتم»… على أي نعمة أشكر الله الآن بقلبي ولساني وعملي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 77;
insert into public.tdb_cards(topic, i, body) select 77, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٣١ – ١٣٤", "q": "وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا ﴿١٣١﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿١٣٢﴾ إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا ﴿١٣٣﴾ مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا ﴿١٣٤﴾", "w": [["وله ما في السموات وما في الأرض", "خلقاً وملكاً وتصرّفاً وتدبيراً."], ["وصّينا", "عهدنا إليهم بالتقوى."], ["أوتوا الكتاب", "اليهود والنصارى."], ["وكيلاً", "الوكيل: من يُفوَّض إليه الأمر كله ويقوم بتدبيره على أحسن الوجوه."], ["ثواب الدنيا", "جزاء العمل فيها."], ["ثواب الآخرة", "جزاء العمل فيها، وهو الجنة."], ["سميعاً بصيراً", "سميعاً لأقوال العباد، بصيراً بأعمالهم، وسيجزيهم بها."]], "m": "لما وعد الله الزوجين المتفرّقين بالإغناء، ذكر أنه يملك ما في السموات وما في الأرض، فهو قادر على إغنائهما. ثم خاطب الأمة جمعاء: ولقد وصّينا الذين أوتوا الكتاب من قبلكم وإياكم أن اتقوا الله، فلا تُقدموا على مخالفته ولا تخرجوا عن طاعته، وإن تكفروا فإن ذلك لا يضرّه شيئاً، فله ما في السموات وما في الأرض، وهو الغني الحميد، وكفى بالله وكيلاً. ثم أخبر أنه قادر على إذهاب الناس كلهم والإتيان بآخرين. ثم رغّب عباده فيما عنده: من كان يريد بعمله ثواب الدنيا فعند الله ثواب الدنيا والآخرة، فلِمَ يقصر العبد عمله على ثواب الدنيا وهو يعلم أن ثواب الآخرة عند الله أيضاً؟ فليطلب الثوابين معاً بالإيمان والتقوى والإحسان، وكان الله سميعاً بصيراً، فلا يُخاف معه ضياع الأعمال.", "h": ["الوصية بالتقوى، وذلك بترك الشرك والمعاصي بعد الإيمان وعمل الصالحات.", "غنى الله تعالى عن سائر خلقه.", "قدرة الله تعالى على إذهاب الناس كلهم والإتيان بغيرهم.", "وجوب الإخلاص في العمل لله تعالى، وحرمة طلب الدنيا بعمل الآخرة."], "k": "«فعند الله ثواب الدنيا والآخرة»… لماذا أطلب بعملي الأقلّ، والله يعطي الاثنين؟"}, {"lbl": "الآيات ١٣٥ – ١٣٧", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿١٣٥﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا ﴿١٣٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا ﴿١٣٧﴾", "w": [["قوّامين", "جمع قوّام، وهو كثير القيام بالعدل."], ["بالقسط", "بالعدل، وهو الاستقامة والتسوية بين الخصوم."], ["تلووا", "تُحرّفوا الشهادة بألسنتكم."], ["أو تُعرضوا", "تتركوا أداءها أو بعض كلماتها."]], "m": "ينادي الله المؤمنين: كونوا قوّامين بالعدل، شهداء لله، إذ بشهادتكم ينتقل الحق من شخص إلى آخر، وقد أقامكم الله شهداء له في الأرض تؤدّى بواسطتكم الحقوق إلى أهلها، فأقيموا الشهادة لله ولو على أنفسكم أو الوالدين والأقربين، غنياً كان المشهود عليه أو فقيراً، فلا يحملنّكم غنى الغني ولا فقر الفقير على تحريف الشهادة أو كتمانها، فالله أولى بهما، فلا تتّبعوا الهوى أن تعدلوا، وإن تلووا ألسنتكم بالشهادة تحريفاً، أو تُعرضوا عنها فتتركوها، فإن الله كان بما تعملون خبيراً. وهي أعظم آية في هذا الباب. ثم دعا المؤمنين إلى تقوية إيمانهم ليبلغوا اليقين، ودعا أهل الكتاب إلى الإيمان الصحيح: آمنوا بالله ورسوله محمد ﷺ، والقرآن الذي نزّل على رسوله، والكتاب الذي أنزل من قبل، ومن يكفر بالله وملائكته وكتبه ورسله واليوم الآخر فقد ضلّ ضلالاً بعيداً. ثم قرّر: إن الذين آمنوا ثم كفروا، ثم آمنوا ثم كفروا، ثم ازدادوا كفراً، لم يكن الله ليغفر لهم ولا ليهديهم سبيلاً.", "h": ["وجوب العدل في القضاء والشهادة.", "حرمة شهادة الزور، وحرمة التخلّي عن الشهادة لمن تعيّنت عليه.", "وجوب الاستمرار على الإيمان وتقويته حتى الموت عليه.", "بيان أركان الإيمان: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر."], "k": "«ولو على أنفسكم أو الوالدين والأقربين»… هل أقول الحق حين يكون ضدّي أو ضدّ من أحب؟"}, {"lbl": "الآيات ١٣٨ – ١٤١", "q": "بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا ﴿١٣٨﴾ ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا ﴿١٣٩﴾ وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا ﴿١٤٠﴾ ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا ﴿١٤١﴾", "w": [["بشّر المنافقين", "البشارة: الخبر الذي تتأثر به بشرة من يُلقى إليه، خيراً كان أو شراً."], ["أولياء", "يوالونهم محبةً ونصرةً لهم على المؤمنين."], ["العزّة", "الغلبة والمنعة."], ["يُستهزأ بها", "يذكرونها استخفافاً بها وإنكاراً لها."], ["يخوضوا", "يتكلموا في موضوع آخر."], ["مثلهم", "في الكفر والإثم."], ["يتربّصون بكم", "ينتظرون متى يحصل لكم انهزام فيعلنون كفرهم."], ["نصيب", "من النصر، وعبّر عنه بالنصيب القليل لأن انتصارهم على المؤمنين قليل."], ["نستحوذ عليكم", "نستولِ عليكم ونمنعكم من المؤمنين إن قاتلوكم."], ["سبيلاً", "طريقاً إلى إذلالهم واستعبادهم والتسلّط عليهم."]], "m": "أمر الله رسوله ﷺ أن يخبر المنافقين، بلفظ البشارة تهكّماً، بأن لهم عذاباً أليماً، ثم وصفهم بأخسّ صفاتهم: الذين يتخذون الكافرين أولياء من دون المؤمنين، يعطونهم محبتهم ونصرتهم، أيبتغون عندهم العزة؟ فإن العزة لله جميعاً، فمن أعزّه الله عزّ، ومن أذلّه ذلّ، وتُطلب العزة بالإيمان وصالح الأعمال. ثم ذكّر المؤمنين بما أنزل عليهم في سورة الأنعام بمكة من النهي عن مجالسة أهل الباطل إذا خاضوا في الطعن في آيات الله، فلما أصبح للمنافقين في المدينة مجالس يخوضون فيها في آيات الله استهزاءً قال: إذا سمعتم آيات الله يُكفر بها ويُستهزأ بها فلا تقعدوا معهم حتى يخوضوا في حديث غيره، إنكم إذاً مثلهم في الإثم والجزاء، إن الله جامع المنافقين والكافرين في جهنم جميعاً. ثم وصفهم: الذين يتربّصون بكم الدوائر، فإن كان لكم فتح من الله قالوا: ألم نكن معكم؟ فأشركونا في الغنيمة، وإن كان للكافرين نصيب قالوا: ألم نستولِ عليكم ونمنعكم من المؤمنين؟ فأعطونا، يمسكون العصا من الوسط. فالله يحكم بينهم يوم القيامة، ولن يجعل الله للكافرين على المؤمنين سبيلاً لاستئصالهم أو إذلالهم ما داموا مؤمنين صادقين.", "h": ["حرمة اتخاذ الكافرين أولياء من دون المؤمنين.", "الباعث على اتخاذ الكافرين أولياء هو الرغبة في العزة، وهذا باطل، فالعزة لله ولا تُطلب إلا منه بالإيمان واتباع منهجه.", "حرمة مجالسة أهل الباطل إذا كانوا يخوضون في آيات الله نقداً واستهزاءً وسخرية.", "الرضا بالكفر كفر، والرضا بالإثم إثم.", "تكفّل الله تعالى بعزة المؤمنين الصادقين ومنعتهم، فلا يسلّط عليهم أعداءه فيستأصلونهم أو يذلّونهم."], "k": "«فلا تقعدوا معهم حتى يخوضوا في حديث غيره»… هل أقوم من مجلس يُستهزأ فيه بالدين، ولو كان مجلساً على الإنترنت؟"}, {"lbl": "الآيتان ١٤٢ – ١٤٣", "q": "إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا ﴿١٤٢﴾ مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا ﴿١٤٣﴾", "w": [["يخادعون الله", "بإظهارهم ما يحب من الإيمان والطاعات، وإخفائهم الكفر."], ["وهو خادعهم", "بالستر عليهم وعدم فضيحتهم وعدم إنزال العقوبة بهم عاجلاً."], ["يراؤون", "يُظهرون الطاعات للمؤمنين كأنهم مؤمنون وما هم بمؤمنين."], ["مذبذبين", "يتردّدون بين المؤمنين والكافرين، فأي جانب عزّ كانوا معه."]], "m": "أخبر الله أن المنافقين يخادعونه بإظهار الإيمان به وبرسوله وهم غير مؤمنين، إذ الخداع أن تُري من تخادعه ما يحبه منك وتستر عنه ما يكرهه، والله عاملهم بالمثل: أراهم ما يحبون، وستر عنهم ما يكرهون، وهو العذاب المعدّ لهم عاجلاً أو آجلاً. وإذا قاموا إلى الصلاة قاموا كسالى متباطئين، لأنهم لا يؤمنون بالثواب الأخروي، يراؤون المؤمنين بالأعمال الصالحة حتى لا يتهموهم بالكفر، ولا يذكرون الله إلا قليلاً في الصلاة وخارجها، لعدم إيمانهم به وعدم حبهم له. وهم مذبذبون بين الكفر والإيمان، لا إلى المؤمنين يسكنون، ولا إلى الكافرين، فهم في تردّد وحسرة دائمة، وهذه حال من يضلّه الله، ومن يضلل الله فلن تجد له سبيلاً.", "h": ["بيان صفات المنافقين.", "قبح الرياء وذمّ المرائين.", "ذم ترك الذكر والتقليل منه، لأمر الله تعالى بالإكثار منه في قوله: «يا أيها الذين آمنوا اذكروا الله ذكراً كثيراً».", "ذم الحيرة والتردّد في الأمور كلها."], "k": "«وإذا قاموا إلى الصلاة قاموا كسالى»… كيف أقوم إلى صلاتي القادمة؟"}, {"lbl": "الآيات ١٤٤ – ١٤٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا ﴿١٤٤﴾ إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا ﴿١٤٥﴾ إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَـٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا ﴿١٤٦﴾ مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا ﴿١٤٧﴾", "w": [["سلطاناً مبيناً", "حجة واضحة لتعذيبكم."], ["الدرك الأسفل", "الدرك كالطابق، والدركة كالدرجة."], ["وأصلحوا", "ما كانوا قد أفسدوه من العقائد والأعمال."], ["واعتصموا بالله", "تمسّكوا بدينه وتوكّلوا عليه."], ["وأخلصوا دينهم لله", "تخلّوا عن النفاق والشرك."]], "m": "ما زال السياق في إرشاد المؤمنين إلى ما يعزّهم ويكمّلهم، فنهاهم عن اتخاذ الكافرين أولياء من دون المؤمنين، بموادّتهم ومناصرتهم والثقة بهم والركون إليهم، وهدّدهم: أتريدون أن تجعلوا لله عليكم حجة واضحة، فيتخلّى عنكم ويسلّط عليكم أعداءه؟ ثم حذّرهم من النفاق أن يتسرّب إلى قلوبهم: إن المنافقين في الدرك الأسفل من النار، ولن تجد لهم نصيراً. ثم فتح باب التوبة رحمةً بعباده: إلا الذين تابوا فآمنوا حق الإيمان، وأصلحوا أعمالهم، واعتصموا بالله ونفضوا أيديهم من الكافرين، وأخلصوا دينهم لله فلم يراؤوا أحداً، فأولئك مع المؤمنين، وسوف يؤتي الله المؤمنين أجراً عظيماً. ثم قرّر غناه عن تعذيب خلقه: ما يفعل الله بعذابكم إن شكرتم وآمنتم؟ فالعبد مهما جنى وأساء إذا تاب وأصلح فآمن وشكر لا يعذّبه، وكان الله شاكراً لا يضيع المعروف عنده، عليماً.", "h": ["حرمة اتخاذ الكافرين أولياء من دون المؤمنين.", "إذا عصى المؤمنون ربهم فاتخذوا الكافرين أولياء سلّط الله عليهم أعداءهم فساموهم الخسف.", "التوبة تجُبّ ما قبلها، حتى إن التائب من ذنبه كمن لا ذنب له، مهما كان الذنب الذي غشيه.", "لا يعذّب الله تعالى المؤمن الشاكر لا في الدنيا ولا في الآخرة، فالإيمان والشكر أمان الإنسان."], "k": "«ما يفعل الله بعذابكم إن شكرتم وآمنتم»… على أي نعمة أشكر الله الآن بقلبي ولساني وعملي؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;